                          chunk = min(m - i + 1,ldwrku)
                          call la_dgemm('N','N',chunk,n,n,one,a(i,1),lda,work(ir) &
                                    ,ldwrkr,zero,work(iu),ldwrku)
                          call la_dlacpy('F',chunk,n,work(iu),ldwrku,a(i,1),lda)

