                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_dlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_dgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right vectors bidiagonalizing l by q in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_dormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors of l in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, compute left
                          ! singular vectors of a in a and compute right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_dbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by n
                             ldwrku = lda
                          else
                             ! work(iu) is lda by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ! generate q in a
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_dorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_dgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_dlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m-1,
                                      ! prefer m*m+3*m+(m-1)*nb)
                          call la_dorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_dbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in a, storing result in vt
                          ! (workspace: need m*m)
                          call la_dgemm('N','N',m,n,m,one,work(iu),ldwrku,a,lda, &
                                    zero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,u,ldu)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_dgebrd(m,m,u,ldu,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_dormbr('P','L','T',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_dbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 else if (wntva) then
                    if (wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! no left singular vectors to be computed
                       if (lwork >= m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(ir) is lda by m
                             ldwrkr = lda
                          else
                             ! work(ir) is m by m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! copy l to work(ir), zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,work(ir + ldwrkr),ldwrkr &
                                    )
                          ! generate q in vt
                          ! (workspace: need m*m + m + n, prefer m*m + m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_dgebrd(m,m,work(ir),ldwrkr,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in work(ir)
                          ! (workspace: need m*m + 4*m-1,
                                      ! prefer m*m+3*m+(m-1)*nb)
                          call la_dorgbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (workspace: need m*m + bdspac)
                          call la_dbdsqr('U',m,m,0,0,s,work(ie),work(ir),ldwrkr, &
                                    dum,1,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_dgemm('N','N',m,n,m,one,work(ir),ldwrkr,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_dlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_dlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_dgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_dormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_dbdsqr('U',m,n,0,0,s,work(ie),vt,ldvt,dum,1, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be overwritten on a
                       if (lwork >= 2*m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*m) then
                             ! work(iu) is lda by m and work(ir) is lda by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + m)*m) then
                             ! work(iu) is lda by m and work(ir) is m by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          else
                             ! work(iu) is m by m and work(ir) is m by m
                             ldwrku = m
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m*m + 2*m, prefer 2*m*m + m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m*m + m + n, prefer 2*m*m + m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to
                          ! work(ir)
                          ! (workspace: need 2*m*m + 4*m,
                                      ! prefer 2*m*m+3*m+2*m*nb)
                          call la_dgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_dlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need 2*m*m + 4*m-1,
                                      ! prefer 2*m*m+3*m+(m-1)*nb)
                          call la_dorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in work(ir)
                          ! (workspace: need 2*m*m + 4*m, prefer 2*m*m + 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,work(ir),ldwrkr,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in work(ir) and computing
                          ! right singular vectors of l in work(iu)
                          ! (workspace: need 2*m*m + bdspac)
                          call la_dbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    work(ir),ldwrkr,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_dgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_dlacpy('F',m,n,a,lda,vt,ldvt)
                          ! copy left singular vectors of a from work(ir) to a
                          call la_dlacpy('F',m,m,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_dlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_dgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_dormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in a and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_dbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by m
                             ldwrku = lda
                          else
                             ! work(iu) is m by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m*m + m + n, prefer m*m + m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_dgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_dlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + (m-1)*nb)
                          call la_dorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_dbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_dgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_dlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_dgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_dorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_dlacpy('L',m,m,a,lda,u,ldu)
                          call la_dlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_dgebrd(m,m,u,ldu,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_dormbr('P','L','T',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_dorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_dbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 end if
              else
                 ! n < mnthr
                 ! path 10t(n greater than m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = ie + m
                 itaup = itauq + m
                 iwork = itaup + m
                 ! bidiagonalize a
                 ! (workspace: need 3*m + n, prefer 3*m + (m + n)*nb)
                 call la_dgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_dlacpy('L',m,m,a,lda,u,ldu)
                    call la_dorgbr('Q',m,m,n,u,ldu,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (workspace: need 3*m + nrvt, prefer 3*m + nrvt*nb)
                    call la_dlacpy('U',m,n,a,lda,vt,ldvt)
                    if (wntva) nrvt = n
                    if (wntvs) nrvt = m
                    call la_dorgbr('P',nrvt,n,m,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_dorgbr('Q',m,m,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m, prefer 3*m + m*nb)
                    call la_dorgbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 iwork = ie + m
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_dbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,u,ldu,dum, &
                               1,work(iwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (workspace: need bdspac)
                    call la_dbdsqr('L',m,ncvt,nru,0,s,work(ie),a,lda,u,ldu,dum, &
                              1,work(iwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_dbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,a,lda,dum, &
                               1,work(iwork),info)
                 end if
              end if
           end if
           ! if la_dbdsqr failed to converge, copy unconverged superdiagonals
           ! to work( 2:minmn )
           if (info /= 0) then
              if (ie > 2) then
                 do i = 1,minmn - 1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
              if (ie < 2) then
                 do i = minmn - 1,1,-1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_dlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm > bignum) call la_dlascl('G',0,0,bignum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
              if (anrm < smlnum) call la_dlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm < smlnum) call la_dlascl('G',0,0,smlnum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = maxwrk
           return
     end subroutine la_dgesvd
#ifdef LA_WITH_XDP
     !> XGESVD: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, optionally computing the left and/or right singular
     !> vectors. The SVD is written
     !> A = U * SIGMA * transpose(V)
     !> where SIGMA is an M-by-N matrix which is zero except for its
     !> min(m,n) diagonal elements, U is an M-by-M orthogonal matrix, and
     !> V is an N-by-N orthogonal matrix.  The diagonal elements of SIGMA
     !> are the singular values of A; they are real and non-negative, and
     !> are returned in descending order.  The first min(m,n) columns of
     !> U and V are the left and right singular vectors of A.
     !> Note that the routine returns V**T, not V.

     subroutine la_xgesvd(jobu,jobvt,m,n,a,lda,s,u,ldu,vt,ldvt,work,lwork,info)
        use la_constants_xdp,only:zero,one

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobu,jobvt
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldvt,lwork,m,n
           ! Array Arguments
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: s(*),u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wntua,wntuas,wntun,wntuo,wntus,wntva,wntvas,wntvn,wntvo, &
                      wntvs
           integer(ilp) :: bdspac,blk,chunk,i,ie,ierr,ir,iscl,itau,itaup,itauq,iu, &
           iwork,ldwrkr,ldwrku,maxwrk,minmn,minwrk,mnthr,ncu,ncvt,nru,nrvt, &
                     wrkbl
           integer(ilp) :: lwork_xgeqrf,lwork_xorgqr_n,lwork_xorgqr_m,lwork_xgebrd, &
                     lwork_xorgbr_p,lwork_xorgbr_q,lwork_xgelqf,lwork_xorglq_n,lwork_xorglq_m
           real(xdp) :: anrm,bignum,eps,smlnum
           ! Local Arrays
           real(xdp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           wntua = la_lsame(jobu,'A')
           wntus = la_lsame(jobu,'S')
           wntuas = wntua .or. wntus
           wntuo = la_lsame(jobu,'O')
           wntun = la_lsame(jobu,'N')
           wntva = la_lsame(jobvt,'A')
           wntvs = la_lsame(jobvt,'S')
           wntvas = wntva .or. wntvs
           wntvo = la_lsame(jobvt,'O')
           wntvn = la_lsame(jobvt,'N')
           lquery = (lwork == -1)
           if (.not. (wntua .or. wntus .or. wntuo .or. wntun)) then
              info = -1
           else if (.not. (wntva .or. wntvs .or. wntvo .or. wntvn) .or. (wntvo .and. wntuo)) &
                     then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldu < 1 .or. (wntuas .and. ldu < m)) then
              info = -9
           else if (ldvt < 1 .or. (wntva .and. ldvt < n) .or. (wntvs .and. ldvt < minmn)) &
                     then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              if (m >= n .and. minmn > 0) then
                 ! compute space needed for la_xbdsqr
                 mnthr = la_ilaenv(6,'XGESVD',jobu//jobvt,m,n,0,0)
                 bdspac = 5*n
                 ! compute space needed for la_xgeqrf
                 call la_xgeqrf(m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xgeqrf = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xorgqr
                 call la_xorgqr(m,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xorgqr_n = int(dum(1),KIND=ilp)
                 call la_xorgqr(m,m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xorgqr_m = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xgebrd
                 call la_xgebrd(n,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                 lwork_xgebrd = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xorgbr p
                 call la_xorgbr('P',n,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xorgbr_p = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xorgbr q
                 call la_xorgbr('Q',n,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xorgbr_q = int(dum(1),KIND=ilp)
                 if (m >= mnthr) then
                    if (wntun) then
                       ! path 1 (m much larger than n, jobu='n')
                       maxwrk = n + lwork_xgeqrf
                       maxwrk = max(maxwrk,3*n + lwork_xgebrd)
                       if (wntvo .or. wntvas) maxwrk = max(maxwrk,3*n + lwork_xorgbr_p)
                       maxwrk = max(maxwrk,bdspac)
                       minwrk = max(4*n,bdspac)
                    else if (wntuo .and. wntvn) then
                       ! path 2 (m much larger than n, jobu='o', jobvt='n')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(n*n + wrkbl,n*n + m*n + n)
                       minwrk = max(3*n + m,bdspac)
                    else if (wntuo .and. wntvas) then
                       ! path 3 (m much larger than n, jobu='o', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(n*n + wrkbl,n*n + m*n + n)
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvn) then
                       ! path 4 (m much larger than n, jobu='s', jobvt='n')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvo) then
                       ! path 5 (m much larger than n, jobu='s', jobvt='o')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvas) then
                       ! path 6 (m much larger than n, jobu='s', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvn) then
                       ! path 7 (m much larger than n, jobu='a', jobvt='n')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvo) then
                       ! path 8 (m much larger than n, jobu='a', jobvt='o')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvas) then
                       ! path 9 (m much larger than n, jobu='a', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_xgeqrf
                       wrkbl = max(wrkbl,n + lwork_xorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    end if
                 else
                    ! path 10 (m at least n, but not much larger)
                    call la_xgebrd(m,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                    lwork_xgebrd = int(dum(1),KIND=ilp)
                    maxwrk = 3*n + lwork_xgebrd
                    if (wntus .or. wntuo) then
                       call la_xorgbr('Q',m,n,n,a,lda,dum(1),dum(1),-1,ierr)
                       lwork_xorgbr_q = int(dum(1),KIND=ilp)
                       maxwrk = max(maxwrk,3*n + lwork_xorgbr_q)
                    end if
                    if (wntua) then
                       call la_xorgbr('Q',m,m,n,a,lda,dum(1),dum(1),-1,ierr)
                       lwork_xorgbr_q = int(dum(1),KIND=ilp)
                       maxwrk = max(maxwrk,3*n + lwork_xorgbr_q)
                    end if
                    if (.not. wntvn) then
                      maxwrk = max(maxwrk,3*n + lwork_xorgbr_p)
                    end if
                    maxwrk = max(maxwrk,bdspac)
                    minwrk = max(3*n + m,bdspac)
                 end if
              else if (minmn > 0) then
                 ! compute space needed for la_xbdsqr
                 mnthr = la_ilaenv(6,'XGESVD',jobu//jobvt,m,n,0,0)
                 bdspac = 5*m
                 ! compute space needed for la_xgelqf
                 call la_xgelqf(m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xgelqf = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xorglq
                 call la_xorglq(n,n,m,dum(1),n,dum(1),dum(1),-1,ierr)
                 lwork_xorglq_n = int(dum(1),KIND=ilp)
                 call la_xorglq(m,n,m,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_xorglq_m = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xgebrd
                 call la_xgebrd(m,m,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                 lwork_xgebrd = int(dum(1),KIND=ilp)
                  ! compute space needed for la_xorgbr p
                 call la_xorgbr('P',m,m,m,a,n,dum(1),dum(1),-1,ierr)
                 lwork_xorgbr_p = int(dum(1),KIND=ilp)
                 ! compute space needed for la_xorgbr q
                 call la_xorgbr('Q',m,m,m,a,n,dum(1),dum(1),-1,ierr)
                 lwork_xorgbr_q = int(dum(1),KIND=ilp)
                 if (n >= mnthr) then
                    if (wntvn) then
                       ! path 1t(n much larger than m, jobvt='n')
                       maxwrk = m + lwork_xgelqf
                       maxwrk = max(maxwrk,3*m + lwork_xgebrd)
                       if (wntuo .or. wntuas) maxwrk = max(maxwrk,3*m + lwork_xorgbr_q)
                       maxwrk = max(maxwrk,bdspac)
                       minwrk = max(4*m,bdspac)
                    else if (wntvo .and. wntun) then
                       ! path 2t(n much larger than m, jobu='n', jobvt='o')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(m*m + wrkbl,m*m + m*n + m)
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvo .and. wntuas) then
                       ! path 3t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='o')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(m*m + wrkbl,m*m + m*n + m)
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntuo) then
                       ! path 5t(n much larger than m, jobu='o', jobvt='s')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='s')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='a')
                       wrkbl = m + lwork_xgelqf
                       wrkbl = max(wrkbl,m + lwork_xorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_xgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_xorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    end if
                 else
                    ! path 10t(n greater than m, but not much larger)
                    call la_xgebrd(m,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                    lwork_xgebrd = int(dum(1),KIND=ilp)
                    maxwrk = 3*m + lwork_xgebrd
                    if (wntvs .or. wntvo) then
                      ! compute space needed for la_xorgbr p
                      call la_xorgbr('P',m,n,m,a,n,dum(1),dum(1),-1,ierr)
                      lwork_xorgbr_p = int(dum(1),KIND=ilp)
                      maxwrk = max(maxwrk,3*m + lwork_xorgbr_p)
                    end if
                    if (wntva) then
                      call la_xorgbr('P',n,n,m,a,n,dum(1),dum(1),-1,ierr)
                      lwork_xorgbr_p = int(dum(1),KIND=ilp)
                      maxwrk = max(maxwrk,3*m + lwork_xorgbr_p)
                    end if
                    if (.not. wntun) then
                       maxwrk = max(maxwrk,3*m + lwork_xorgbr_q)
                    end if
                    maxwrk = max(maxwrk,bdspac)
                    minwrk = max(3*m + n,bdspac)
                 end if
              end if
              maxwrk = max(maxwrk,minwrk)
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('XGESVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              return
           end if
           ! get machine constants
           eps = la_xlamch('P')
           smlnum = sqrt(la_xlamch('S'))/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_xlange('M',m,n,a,lda,dum)
           iscl = 0
           if (anrm > zero .and. anrm < smlnum) then
              iscl = 1
              call la_xlascl('G',0,0,anrm,smlnum,m,n,a,lda,ierr)
           else if (anrm > bignum) then
              iscl = 1
              call la_xlascl('G',0,0,anrm,bignum,m,n,a,lda,ierr)
           end if
           if (m >= n) then
              ! a has at least as many rows as columns. if a has sufficiently
              ! more rows than columns, first reduce using the qr
              ! decomposition (if sufficient workspace available)
              if (m >= mnthr) then
                 if (wntun) then
                    ! path 1 (m much larger than n, jobu='n')
                    ! no left singular vectors to be computed
                    itau = 1
                    iwork = itau + n
                    ! compute a=q*r
                    ! (workspace: need 2*n, prefer n + n*nb)
                    call la_xgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out below r
                    if (n > 1) then
                       call la_xlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
                    end if
                    ie = 1
                    itauq = ie + n
                    itaup = itauq + n
                    iwork = itaup + n
                    ! bidiagonalize r in a
                    ! (workspace: need 4*n, prefer 3*n + 2*n*nb)
                    call la_xgebrd(n,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(iwork),lwork - iwork + 1,ierr)
                    ncvt = 0
                    if (wntvo .or. wntvas) then
                       ! if right singular vectors desired, generate p'.
                       ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                       call la_xorgbr('P',n,n,n,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       ncvt = n
                    end if
                    iwork = ie + n
                    ! perform bidiagonal qr iteration, computing right
                    ! singular vectors of a in a if desired
                    ! (workspace: need bdspac)
                    call la_xbdsqr('U',n,ncvt,0,0,s,work(ie),a,lda,dum,1,dum,1, &
                              work(iwork),info)
                    ! if right singular vectors desired in vt, copy them there
                    if (wntvas) call la_xlacpy('F',n,n,a,lda,vt,ldvt)
                 else if (wntuo .and. wntvn) then
                    ! path 2 (m much larger than n, jobu='o', jobvt='n')
                    ! n left singular vectors to be overwritten on a and
                    ! no right singular vectors to be computed
                    if (lwork >= n*n + max(4*n,bdspac)) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n + n) + lda*n) then
                          ! work(iu) is lda by n, work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n + n) + n*n) then
                          ! work(iu) is lda by n, work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n, work(ir) is n by n
                          ldwrku = (lwork - n*n - n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_xgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to work(ir) and zero out below it
                       call la_xlacpy('U',n,n,a,lda,work(ir),ldwrkr)
                       call la_xlaset('L',n - 1,n - 1,zero,zero,work(ir + 1),ldwrkr)

                       ! generate q in a
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_xorgqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + n
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + 2*n*nb)
                       call la_xgebrd(n,n,work(ir),ldwrkr,s,work(ie),work(itauq), &
                                 work(itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing r
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + n*nb)
                       call la_xorgbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       iwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of r in work(ir)
                       ! (workspace: need n*n + bdspac)
                       call la_xbdsqr('U',n,0,n,0,s,work(ie),dum,1,work(ir), &
                                 ldwrkr,dum,1,work(iwork),info)
