                       iwork = itau + n
                       ! compute a=q*r
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to vt, zeroing out below it
                       call la_qlacpy('U',n,n,a,lda,vt,ldvt)
                       if (n > 1) call la_qlaset('L',n - 1,n - 1,zero,zero,vt(2,1),ldvt)

                       ! generate q in a
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qorgqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + n
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in vt, copying result to work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + 2*n*nb)
                       call la_qgebrd(n,n,vt,ldvt,s,work(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       call la_qlacpy('L',n,n,vt,ldvt,work(ir),ldwrkr)
                       ! generate left vectors bidiagonalizing r in work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + n*nb)
                       call la_qorgbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
