                          call la_qorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right vectors bidiagonalizing l by q in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors of l in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, compute left
                          ! singular vectors of a in a and compute right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by n
                             ldwrku = lda
                          else
                             ! work(iu) is lda by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ! generate q in a
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m-1,
                                      ! prefer m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in a, storing result in vt
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,a,lda, &
                                    zero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,u,ldu)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,u,ldu,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 else if (wntva) then
                    if (wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! no left singular vectors to be computed
                       if (lwork >= m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(ir) is lda by m
                             ldwrkr = lda
                          else
                             ! work(ir) is m by m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! copy l to work(ir), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(ir + ldwrkr),ldwrkr &
                                    )
                          ! generate q in vt
                          ! (workspace: need m*m + m + n, prefer m*m + m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(ir),ldwrkr,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in work(ir)
                          ! (workspace: need m*m + 4*m-1,
                                      ! prefer m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,0,0,s,work(ie),work(ir),ldwrkr, &
                                    dum,1,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(ir),ldwrkr,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,0,0,s,work(ie),vt,ldvt,dum,1, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be overwritten on a
                       if (lwork >= 2*m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*m) then
                             ! work(iu) is lda by m and work(ir) is lda by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + m)*m) then
                             ! work(iu) is lda by m and work(ir) is m by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          else
                             ! work(iu) is m by m and work(ir) is m by m
                             ldwrku = m
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m*m + 2*m, prefer 2*m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m*m + m + n, prefer 2*m*m + m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to
                          ! work(ir)
                          ! (workspace: need 2*m*m + 4*m,
                                      ! prefer 2*m*m+3*m+2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need 2*m*m + 4*m-1,
                                      ! prefer 2*m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in work(ir)
                          ! (workspace: need 2*m*m + 4*m, prefer 2*m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,work(ir),ldwrkr,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in work(ir) and computing
                          ! right singular vectors of l in work(iu)
                          ! (workspace: need 2*m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    work(ir),ldwrkr,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                          ! copy left singular vectors of a from work(ir) to a
                          call la_qlacpy('F',m,m,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in a and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by m
                             ldwrku = lda
                          else
                             ! work(iu) is m by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m*m + m + n, prefer m*m + m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + (m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,u,ldu)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,u,ldu,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 end if
              else
                 ! n < mnthr
                 ! path 10t(n greater than m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = ie + m
                 itaup = itauq + m
                 iwork = itaup + m
                 ! bidiagonalize a
                 ! (workspace: need 3*m + n, prefer 3*m + (m + n)*nb)
                 call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_qlacpy('L',m,m,a,lda,u,ldu)
                    call la_qorgbr('Q',m,m,n,u,ldu,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (workspace: need 3*m + nrvt, prefer 3*m + nrvt*nb)
                    call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                    if (wntva) nrvt = n
                    if (wntvs) nrvt = m
                    call la_qorgbr('P',nrvt,n,m,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_qorgbr('Q',m,m,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m, prefer 3*m + m*nb)
                    call la_qorgbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 iwork = ie + m
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,u,ldu,dum, &
                               1,work(iwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),a,lda,u,ldu,dum, &
                              1,work(iwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,a,lda,dum, &
                               1,work(iwork),info)
                 end if
              end if
           end if
           ! if la_qbdsqr failed to converge, copy unconverged superdiagonals
           ! to work( 2:minmn )
           if (info /= 0) then
              if (ie > 2) then
                 do i = 1,minmn - 1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
              if (ie < 2) then
                 do i = minmn - 1,1,-1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
              if (anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = maxwrk
           return
     end subroutine la_qgesvd
#endif

     !> SGESVDQ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_sgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,work,lwork,rwork,lrwork,info)
        use la_constants_sp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lwork
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: u(ldu,*),v(ldv,*),work(*)
           real(sp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,iwoff,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_sgelqf,lwrk_sgesvd,lwrk_sgesvd2,lwrk_sgeqp3, &
           lwrk_sgeqrf,lwrk_sormlq,lwrk_sormqr,lwrk_sormqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lworq,lworq2,lwunlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(sp) :: big,epsln,rtmp,sconda,sfmin
           ! Local Arrays
           real(sp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! Executable Statements
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              if (conda) then
                 iminwrk = max(1,n + m - 1 + n)
              else
                 iminwrk = max(1,n + m - 1)
              end if
              rminwrk = max(2,m)
           else
              if (conda) then
                 iminwrk = max(1,n + n)
              else
                 iminwrk = max(1,n)
              end if
              rminwrk = 2
           end if
           lquery = (liwork == -1 .or. lwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_sgeqp3 Of An M X N Matrix
              lwqp3 = 3*n + 1
              ! Minimal Workspace Length For la_sormqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lworq = max(n,1)
              else if (wntua) then
                  lworq = max(m,1)
              end if
              ! Minimal Workspace Length For la_spocon Of An N X N Matrix
              lwcon = 3*n
              ! la_sgesvd Of An N X N Matrix
              lwsvd = max(5*n,1)
              if (lquery) then
                  call la_sgeqp3(m,n,a,lda,iwork,rdummy,rdummy,-1,ierr)
                  lwrk_sgeqp3 = int(rdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_sormqr('L','N',m,n,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_sormqr = int(rdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_sormqr('L','N',m,m,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_sormqr = int(rdummy(1),KIND=ilp)
                  else
                      lwrk_sormqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_sgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                ierr)
                      lwrk_sgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_sgeqp3,n + lwcon,lwrk_sgesvd)
                      else
                         optwrk = max(n + lwrk_sgeqp3,lwrk_sgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lworq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lworq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_sgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     else
                        call la_sgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     end if
                     lwrk_sgesvd = int(rdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_sgeqp3,lwcon,lwrk_sgesvd,lwrk_sormqr)
                     else
                         optwrk = n + max(lwrk_sgeqp3,lwrk_sgesvd,lwrk_sormqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_sgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      else
                          call la_sgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      end if
                      lwrk_sgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_sgeqp3,lwcon,lwrk_sgesvd)
                      else
                          optwrk = n + max(lwrk_sgeqp3,lwrk_sgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_sgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_sgesvd
                         lwsvd2 = max(5*(n/2),1)
                         lworq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lworq2,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_sgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(5*(n/2),1)
                         lwunlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lwunlq,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_sgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_sgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_sgeqp3,lwrk_sgesvd,lwrk_sormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_sgeqrf(n,n/2,u,ldu,rdummy,rdummy,-1,ierr)
                            lwrk_sgeqrf = int(rdummy(1),KIND=ilp)
                            call la_sgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                       -1,ierr)
                            lwrk_sgesvd2 = int(rdummy(1),KIND=ilp)
                            call la_sormqr('R','C',n,n,n/2,u,ldu,rdummy,v,ldv, &
                                      rdummy,-1,ierr)
                            lwrk_sormqr2 = int(rdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_sgeqp3,n/2 + lwrk_sgeqrf,n/2 + lwrk_sgesvd2,n/2 + &
                                      lwrk_sormqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_sgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_sgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_sgeqp3,lwrk_sgesvd,lwrk_sormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_sgelqf(n/2,n,u,ldu,rdummy,rdummy,-1,ierr)
                           lwrk_sgelqf = int(rdummy(1),KIND=ilp)
                           call la_sgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                      -1,ierr)
                           lwrk_sgesvd2 = int(rdummy(1),KIND=ilp)
                           call la_sormlq('R','N',n,n,n/2,u,ldu,rdummy,v,ldv,rdummy, &
                                     -1,ierr)
                           lwrk_sormlq = int(rdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_sgeqp3,n/2 + lwrk_sgelqf,n/2 + lwrk_sgesvd2,n/2 + &
                                     lwrk_sormlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('SGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               work(1) = optwrk
               work(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_slamch('O')
           ascaled = .false.
           iwoff = 1
           if (rowprm) then
                 iwoff = m
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_icamax(n,a(p,1),lda)) )
                     ! [[la_slange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_slange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('SGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_isamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_slaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_slaset('G',m,n,zero,one,u,ldu)
                    if (wntua) call la_slaset('G',m,m,zero,one,u,ldu)
                    if (wntva) call la_slaset('G',n,n,zero,one,v,ldv)
                    if (wntuf) then
                        call la_slaset('G',n,1,zero,zero,work,n)
                        call la_slaset('G',m,n,zero,one,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=sp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_slascl('G',0,0,sqrt(real(m,KIND=sp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_slaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_slange('M',m,n,a,lda,rdummy)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('SGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=sp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_slascl('G',0,0,sqrt(real(m,KIND=sp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_sgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_slamch('E')
           sfmin = la_slamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=sp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_slamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_slacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_snrm2(p,v(1,p),1)
                       call la_sscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_spocon('U',nr,v,ldv,one,rtmp,work,iwork(n + iwoff),ierr &
                                  )
                    else
                        call la_spocon('U',nr,v,ldv,one,rtmp,work(n + 1),iwork(n + iwoff), &
                                  ierr)
                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**t = [a](1:nr,1:n)**t
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**t and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    do q = p + 1,n
                       a(q,p) = a(p,q)
                       if (q <= nr) a(p,q) = zero
                    end do
                 end do
                 call la_sgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_sgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_sgesvd to r**t
                  ! .. copy r**t into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_sgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                    end do
              else
                  ! Apply la_sgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_slacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_sgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_slaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_slaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                     call la_slaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_sormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_slaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_sgesvd to r**t
                  ! .. copy r**t into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = (a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_sgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_slapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_slaset('G',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                     call la_sgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                               lwork - n,info)
                     do p = 1,n
                        do q = p + 1,n
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                     end do
                     call la_slapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_sgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_slacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_sgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_slapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_slaset('G',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                      call la_sgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                lwork - n,info)
                      call la_slapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the transposed matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_sgesvd to r**t [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite [v], the nr right
                 ! singular vectors of r**t stored in [u](1:nr,1:nr) as transposed
                    call la_sgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                              lwork - n,info)
                    ! Assemble V
                    do p = 1,nr
                       do q = p + 1,nr
                          rtmp = v(q,p)
                          v(q,p) = v(p,q)
                          v(p,q) = rtmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_slapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_slaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_slaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_slaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'sgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)

                        call la_slaset('A',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                        call la_sgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                                  lwork - n,info)
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = v(q,p)
                              v(q,p) = v(p,q)
                              v(p,q) = rtmp
                           end do
                        end do
                        call la_slapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = u(q,p)
                              u(q,p) = u(p,q)
                              u(p,q) = rtmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_slaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_slaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_slaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**t into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,u(1,nr + 2),ldu)

                        call la_sgeqrf(n,nr,u(1,nr + 1),ldu,work(n + 1),work(n + nr + 1),lwork - &
                                  n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = u(p,nr + q)
                            end do
                        end do
                       call la_slaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_sgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + 1) &
                                 ,lwork - n - nr,info)
                       call la_slaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_slaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_slaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_sormqr('R','C',n,n,nr,u(1,nr + 1),ldu,work(n + 1),v,ldv,work( &
                                 n + nr + 1),lwork - n - nr,ierr)
                       call la_slapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_slaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_slaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_slaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_sgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_slacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_sgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_slapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_slaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_slaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_slaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'sgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_slacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_slaset('A',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                       call la_sgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                 lwork - n,info)
                       call la_slapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the transposed matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_slaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_slaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_slaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_slacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_slaset('L',nr - 1,nr - 1,zero,zero,u(nr + 2,1),ldu)

                       call la_sgelqf(nr,n,u(nr + 1,1),ldu,work(n + 1),work(n + nr + 1),lwork - n - &
                                 nr,ierr)
                       call la_slacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_slaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_sgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + &
                                 1),lwork - n - nr,info)
                       call la_slaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_slaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_slaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_sormlq('R','N',n,n,nr,u(nr + 1,1),ldu,work(n + 1),v,ldv,work(n + &
                                 nr + 1),lwork - n - nr,ierr)
                       call la_slapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_slaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_slaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_slaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**t or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_sormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_slaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_slaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_slascl('G',0,0,one,sqrt(real(m,KIND=sp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_sgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_sgesvdq
     !> DGESVDQ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_dgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,work,lwork,rwork,lrwork,info)
        use la_constants_dp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lwork
           ! Array Arguments
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: u(ldu,*),v(ldv,*),work(*)
           real(dp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,iwoff,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_dgelqf,lwrk_dgesvd,lwrk_dgesvd2,lwrk_dgeqp3, &
           lwrk_dgeqrf,lwrk_dormlq,lwrk_dormqr,lwrk_dormqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lworq,lworq2,lworlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(dp) :: big,epsln,rtmp,sconda,sfmin
           ! Local Arrays
           real(dp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              if (conda) then
                 iminwrk = max(1,n + m - 1 + n)
              else
                 iminwrk = max(1,n + m - 1)
              end if
              rminwrk = max(2,m)
           else
              if (conda) then
                 iminwrk = max(1,n + n)
              else
                 iminwrk = max(1,n)
              end if
              rminwrk = 2
           end if
           lquery = (liwork == -1 .or. lwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_dgeqp3 Of An M X N Matrix
              lwqp3 = 3*n + 1
              ! Minimal Workspace Length For la_dormqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lworq = max(n,1)
              else if (wntua) then
                  lworq = max(m,1)
              end if
              ! Minimal Workspace Length For la_dpocon Of An N X N Matrix
              lwcon = 3*n
              ! la_dgesvd Of An N X N Matrix
              lwsvd = max(5*n,1)
              if (lquery) then
                  call la_dgeqp3(m,n,a,lda,iwork,rdummy,rdummy,-1,ierr)
                  lwrk_dgeqp3 = int(rdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_dormqr('L','N',m,n,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_dormqr = int(rdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_dormqr('L','N',m,m,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_dormqr = int(rdummy(1),KIND=ilp)
                  else
                      lwrk_dormqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_dgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                ierr)
                      lwrk_dgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_dgeqp3,n + lwcon,lwrk_dgesvd)
                      else
                         optwrk = max(n + lwrk_dgeqp3,lwrk_dgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lworq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lworq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_dgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     else
                        call la_dgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     end if
                     lwrk_dgesvd = int(rdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_dgeqp3,lwcon,lwrk_dgesvd,lwrk_dormqr)
                     else
                         optwrk = n + max(lwrk_dgeqp3,lwrk_dgesvd,lwrk_dormqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_dgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      else
                          call la_dgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      end if
                      lwrk_dgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_dgeqp3,lwcon,lwrk_dgesvd)
                      else
                          optwrk = n + max(lwrk_dgeqp3,lwrk_dgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_dgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_dgesvd
                         lwsvd2 = max(5*(n/2),1)
                         lworq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lworq2,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_dgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(5*(n/2),1)
                         lworlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lworlq,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_dgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_dgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_dgeqp3,lwrk_dgesvd,lwrk_dormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_dgeqrf(n,n/2,u,ldu,rdummy,rdummy,-1,ierr)
                            lwrk_dgeqrf = int(rdummy(1),KIND=ilp)
                            call la_dgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                       -1,ierr)
                            lwrk_dgesvd2 = int(rdummy(1),KIND=ilp)
                            call la_dormqr('R','C',n,n,n/2,u,ldu,rdummy,v,ldv, &
                                      rdummy,-1,ierr)
                            lwrk_dormqr2 = int(rdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_dgeqp3,n/2 + lwrk_dgeqrf,n/2 + lwrk_dgesvd2,n/2 + &
                                      lwrk_dormqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_dgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_dgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_dgeqp3,lwrk_dgesvd,lwrk_dormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_dgelqf(n/2,n,u,ldu,rdummy,rdummy,-1,ierr)
                           lwrk_dgelqf = int(rdummy(1),KIND=ilp)
                           call la_dgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                      -1,ierr)
                           lwrk_dgesvd2 = int(rdummy(1),KIND=ilp)
                           call la_dormlq('R','N',n,n,n/2,u,ldu,rdummy,v,ldv,rdummy, &
                                     -1,ierr)
                           lwrk_dormlq = int(rdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_dgeqp3,n/2 + lwrk_dgelqf,n/2 + lwrk_dgesvd2,n/2 + &
                                     lwrk_dormlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('DGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               work(1) = optwrk
               work(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_dlamch('O')
           ascaled = .false.
           iwoff = 1
           if (rowprm) then
                 iwoff = m
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_icamax(n,a(p,1),lda)) )
                     ! [[la_dlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_dlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('DGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_idamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_dlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_dlaset('G',m,n,zero,one,u,ldu)
                    if (wntua) call la_dlaset('G',m,m,zero,one,u,ldu)
                    if (wntva) call la_dlaset('G',n,n,zero,one,v,ldv)
                    if (wntuf) then
                        call la_dlaset('G',n,1,zero,zero,work,n)
                        call la_dlaset('G',m,n,zero,one,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=dp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_dlascl('G',0,0,sqrt(real(m,KIND=dp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_dlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_dlange('M',m,n,a,lda,rdummy)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('DGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=dp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_dlascl('G',0,0,sqrt(real(m,KIND=dp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_dgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_dlamch('E')
           sfmin = la_dlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=dp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_dlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_dlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_dnrm2(p,v(1,p),1)
                       call la_dscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_dpocon('U',nr,v,ldv,one,rtmp,work,iwork(n + iwoff),ierr &
                                  )
                    else
                        call la_dpocon('U',nr,v,ldv,one,rtmp,work(n + 1),iwork(n + iwoff), &
                                  ierr)
                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**t = [a](1:nr,1:n)**t
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**t and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    do q = p + 1,n
                       a(q,p) = a(p,q)
                       if (q <= nr) a(p,q) = zero
                    end do
                 end do
                 call la_dgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_dgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_dgesvd to r**t
                  ! .. copy r**t into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_dgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                    end do
              else
                  ! Apply la_dgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_dlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_dgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_dlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_dlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                     call la_dlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_dormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_dlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_dgesvd to r**t
                  ! .. copy r**t into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = (a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_dgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_dlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_dlaset('G',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                     call la_dgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                               lwork - n,info)
                     do p = 1,n
                        do q = p + 1,n
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                     end do
                     call la_dlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_dgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_dlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_dgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_dlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_dlaset('G',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                      call la_dgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                lwork - n,info)
                      call la_dlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the transposed matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_dgesvd to r**t [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite [v], the nr right
                 ! singular vectors of r**t stored in [u](1:nr,1:nr) as transposed
                    call la_dgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                              lwork - n,info)
                    ! Assemble V
                    do p = 1,nr
                       do q = p + 1,nr
                          rtmp = v(q,p)
                          v(q,p) = v(p,q)
                          v(p,q) = rtmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_dlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_dlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_dlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_dlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'dgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)

                        call la_dlaset('A',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                        call la_dgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                                  lwork - n,info)
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = v(q,p)
                              v(q,p) = v(p,q)
                              v(p,q) = rtmp
                           end do
                        end do
                        call la_dlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = u(q,p)
                              u(q,p) = u(p,q)
                              u(p,q) = rtmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_dlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_dlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_dlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**t into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,u(1,nr + 2),ldu)

                        call la_dgeqrf(n,nr,u(1,nr + 1),ldu,work(n + 1),work(n + nr + 1),lwork - &
                                  n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = u(p,nr + q)
                            end do
                        end do
                       call la_dlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_dgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + 1) &
                                 ,lwork - n - nr,info)
                       call la_dlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_dlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_dlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_dormqr('R','C',n,n,nr,u(1,nr + 1),ldu,work(n + 1),v,ldv,work( &
                                 n + nr + 1),lwork - n - nr,ierr)
                       call la_dlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_dlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_dlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_dlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_dgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_dlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_dgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_dlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_dlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_dlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_dlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'dgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_dlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_dlaset('A',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                       call la_dgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                 lwork - n,info)
                       call la_dlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the transposed matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_dlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_dlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_dlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_dlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_dlaset('L',nr - 1,nr - 1,zero,zero,u(nr + 2,1),ldu)

                       call la_dgelqf(nr,n,u(nr + 1,1),ldu,work(n + 1),work(n + nr + 1),lwork - n - &
                                 nr,ierr)
                       call la_dlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_dlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_dgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + &
                                 1),lwork - n - nr,info)
                       call la_dlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_dlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_dlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_dormlq('R','N',n,n,nr,u(nr + 1,1),ldu,work(n + 1),v,ldv,work(n + &
                                 nr + 1),lwork - n - nr,ierr)
                       call la_dlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_dlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_dlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_dlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**t or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_dormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_dlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_dlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_dlascl('G',0,0,one,sqrt(real(m,KIND=dp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_dgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_dgesvdq
#ifdef LA_WITH_XDP
     !> XGESVDQ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_xgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,work,lwork,rwork,lrwork,info)
        use la_constants_xdp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lwork
           ! Array Arguments
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: u(ldu,*),v(ldv,*),work(*)
           real(xdp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,iwoff,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_xgelqf,lwrk_xgesvd,lwrk_xgesvd2,lwrk_xgeqp3, &
           lwrk_xgeqrf,lwrk_xormlq,lwrk_xormqr,lwrk_xormqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lworq,lworq2,lworlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(xdp) :: big,epsln,rtmp,sconda,sfmin
           ! Local Arrays
           real(xdp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              if (conda) then
                 iminwrk = max(1,n + m - 1 + n)
              else
                 iminwrk = max(1,n + m - 1)
              end if
              rminwrk = max(2,m)
           else
              if (conda) then
                 iminwrk = max(1,n + n)
              else
                 iminwrk = max(1,n)
              end if
              rminwrk = 2
           end if
           lquery = (liwork == -1 .or. lwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_xgeqp3 Of An M X N Matrix
              lwqp3 = 3*n + 1
              ! Minimal Workspace Length For la_xormqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lworq = max(n,1)
              else if (wntua) then
                  lworq = max(m,1)
              end if
              ! Minimal Workspace Length For la_xpocon Of An N X N Matrix
              lwcon = 3*n
              ! la_xgesvd Of An N X N Matrix
              lwsvd = max(5*n,1)
              if (lquery) then
                  call la_xgeqp3(m,n,a,lda,iwork,rdummy,rdummy,-1,ierr)
                  lwrk_xgeqp3 = int(rdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_xormqr('L','N',m,n,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_xormqr = int(rdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_xormqr('L','N',m,m,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_xormqr = int(rdummy(1),KIND=ilp)
                  else
                      lwrk_xormqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_xgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                ierr)
                      lwrk_xgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_xgeqp3,n + lwcon,lwrk_xgesvd)
                      else
                         optwrk = max(n + lwrk_xgeqp3,lwrk_xgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lworq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lworq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_xgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     else
                        call la_xgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     end if
                     lwrk_xgesvd = int(rdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_xgeqp3,lwcon,lwrk_xgesvd,lwrk_xormqr)
                     else
                         optwrk = n + max(lwrk_xgeqp3,lwrk_xgesvd,lwrk_xormqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_xgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      else
                          call la_xgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      end if
                      lwrk_xgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_xgeqp3,lwcon,lwrk_xgesvd)
                      else
                          optwrk = n + max(lwrk_xgeqp3,lwrk_xgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_xgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_xgesvd
                         lwsvd2 = max(5*(n/2),1)
                         lworq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lworq2,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_xgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(5*(n/2),1)
                         lworlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lworlq,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_xgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_xgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_xgeqp3,lwrk_xgesvd,lwrk_xormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_xgeqrf(n,n/2,u,ldu,rdummy,rdummy,-1,ierr)
                            lwrk_xgeqrf = int(rdummy(1),KIND=ilp)
                            call la_xgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                       -1,ierr)
                            lwrk_xgesvd2 = int(rdummy(1),KIND=ilp)
                            call la_xormqr('R','C',n,n,n/2,u,ldu,rdummy,v,ldv, &
                                      rdummy,-1,ierr)
                            lwrk_xormqr2 = int(rdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_xgeqp3,n/2 + lwrk_xgeqrf,n/2 + lwrk_xgesvd2,n/2 + &
                                      lwrk_xormqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_xgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_xgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_xgeqp3,lwrk_xgesvd,lwrk_xormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_xgelqf(n/2,n,u,ldu,rdummy,rdummy,-1,ierr)
                           lwrk_xgelqf = int(rdummy(1),KIND=ilp)
                           call la_xgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                      -1,ierr)
                           lwrk_xgesvd2 = int(rdummy(1),KIND=ilp)
                           call la_xormlq('R','N',n,n,n/2,u,ldu,rdummy,v,ldv,rdummy, &
                                     -1,ierr)
                           lwrk_xormlq = int(rdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_xgeqp3,n/2 + lwrk_xgelqf,n/2 + lwrk_xgesvd2,n/2 + &
                                     lwrk_xormlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('XGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               work(1) = optwrk
               work(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_xlamch('O')
           ascaled = .false.
           iwoff = 1
           if (rowprm) then
                 iwoff = m
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_izamax(n,a(p,1),lda)) )
                     ! [[la_xlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_xlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('XGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_ixamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_xlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_xlaset('G',m,n,zero,one,u,ldu)
                    if (wntua) call la_xlaset('G',m,m,zero,one,u,ldu)
                    if (wntva) call la_xlaset('G',n,n,zero,one,v,ldv)
                    if (wntuf) then
                        call la_xlaset('G',n,1,zero,zero,work,n)
                        call la_xlaset('G',m,n,zero,one,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=xdp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_xlascl('G',0,0,sqrt(real(m,KIND=xdp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_xlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_xlange('M',m,n,a,lda,rdummy)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('XGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=xdp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_xlascl('G',0,0,sqrt(real(m,KIND=xdp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_xgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_xlamch('E')
           sfmin = la_xlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=xdp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_xlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_xlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_xnrm2(p,v(1,p),1)
                       call la_xscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_xpocon('U',nr,v,ldv,one,rtmp,work,iwork(n + iwoff),ierr &
                                  )
                    else
                        call la_xpocon('U',nr,v,ldv,one,rtmp,work(n + 1),iwork(n + iwoff), &
                                  ierr)
                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**t = [a](1:nr,1:n)**t
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**t and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    do q = p + 1,n
                       a(q,p) = a(p,q)
                       if (q <= nr) a(p,q) = zero
                    end do
                 end do
                 call la_xgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_xgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_xgesvd to r**t
                  ! .. copy r**t into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_xgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                    end do
              else
                  ! Apply la_xgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_xlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_xgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_xlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_xlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                     call la_xlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_xormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_xlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_xgesvd to r**t
                  ! .. copy r**t into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = (a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_xgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_xlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_xlaset('G',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                     call la_xgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                               lwork - n,info)
                     do p = 1,n
                        do q = p + 1,n
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                     end do
                     call la_xlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_xgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_xlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_xgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_xlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_xlaset('G',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                      call la_xgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                lwork - n,info)
                      call la_xlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the transposed matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_xgesvd to r**t [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite [v], the nr right
                 ! singular vectors of r**t stored in [u](1:nr,1:nr) as transposed
                    call la_xgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                              lwork - n,info)
                    ! Assemble V
                    do p = 1,nr
                       do q = p + 1,nr
                          rtmp = v(q,p)
                          v(q,p) = v(p,q)
                          v(p,q) = rtmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_xlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_xlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_xlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_xlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'xgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)

                        call la_xlaset('A',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                        call la_xgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                                  lwork - n,info)
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = v(q,p)
                              v(q,p) = v(p,q)
                              v(p,q) = rtmp
                           end do
                        end do
                        call la_xlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = u(q,p)
                              u(q,p) = u(p,q)
                              u(p,q) = rtmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_xlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_xlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_xlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**t into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,u(1,nr + 2),ldu)

                        call la_xgeqrf(n,nr,u(1,nr + 1),ldu,work(n + 1),work(n + nr + 1),lwork - &
                                  n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = u(p,nr + q)
                            end do
                        end do
                       call la_xlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_xgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + 1) &
                                 ,lwork - n - nr,info)
                       call la_xlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_xlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_xlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_xormqr('R','C',n,n,nr,u(1,nr + 1),ldu,work(n + 1),v,ldv,work( &
                                 n + nr + 1),lwork - n - nr,ierr)
                       call la_xlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_xlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_xlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_xlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_xgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_xlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_xgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_xlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_xlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_xlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_xlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'xgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_xlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_xlaset('A',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                       call la_xgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                 lwork - n,info)
                       call la_xlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the transposed matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_xlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_xlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_xlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_xlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_xlaset('L',nr - 1,nr - 1,zero,zero,u(nr + 2,1),ldu)

                       call la_xgelqf(nr,n,u(nr + 1,1),ldu,work(n + 1),work(n + nr + 1),lwork - n - &
                                 nr,ierr)
                       call la_xlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_xlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_xgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + &
                                 1),lwork - n - nr,info)
                       call la_xlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_xlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_xlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_xormlq('R','N',n,n,nr,u(nr + 1,1),ldu,work(n + 1),v,ldv,work(n + &
                                 nr + 1),lwork - n - nr,ierr)
                       call la_xlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_xlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_xlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_xlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**t or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_xormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_xlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_xlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_xlascl('G',0,0,one,sqrt(real(m,KIND=xdp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_xgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_xgesvdq
#endif
#ifdef LA_WITH_QP
     !> QGESVDQ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_qgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,work,lwork,rwork,lrwork,info)
        use la_constants_qp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lwork
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: u(ldu,*),v(ldv,*),work(*)
           real(qp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,iwoff,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_qgelqf,lwrk_qgesvd,lwrk_qgesvd2,lwrk_qgeqp3, &
           lwrk_qgeqrf,lwrk_qormlq,lwrk_qormqr,lwrk_qormqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lworq,lworq2,lworlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(qp) :: big,epsln,rtmp,sconda,sfmin
           ! Local Arrays
           real(qp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              if (conda) then
                 iminwrk = max(1,n + m - 1 + n)
              else
                 iminwrk = max(1,n + m - 1)
              end if
              rminwrk = max(2,m)
           else
              if (conda) then
                 iminwrk = max(1,n + n)
              else
                 iminwrk = max(1,n)
              end if
              rminwrk = 2
           end if
           lquery = (liwork == -1 .or. lwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_qgeqp3 Of An M X N Matrix
              lwqp3 = 3*n + 1
              ! Minimal Workspace Length For la_qormqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lworq = max(n,1)
              else if (wntua) then
                  lworq = max(m,1)
              end if
              ! Minimal Workspace Length For la_qpocon Of An N X N Matrix
              lwcon = 3*n
              ! la_qgesvd Of An N X N Matrix
              lwsvd = max(5*n,1)
              if (lquery) then
                  call la_qgeqp3(m,n,a,lda,iwork,rdummy,rdummy,-1,ierr)
                  lwrk_qgeqp3 = int(rdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_qormqr('L','N',m,n,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_qormqr = int(rdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_qormqr('L','N',m,m,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_qormqr = int(rdummy(1),KIND=ilp)
                  else
                      lwrk_qormqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_qgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                ierr)
                      lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_qgeqp3,n + lwcon,lwrk_qgesvd)
                      else
                         optwrk = max(n + lwrk_qgeqp3,lwrk_qgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lworq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lworq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_qgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     else
                        call la_qgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     end if
                     lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_qgeqp3,lwcon,lwrk_qgesvd,lwrk_qormqr)
                     else
                         optwrk = n + max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_qgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      else
                          call la_qgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      end if
                      lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_qgeqp3,lwcon,lwrk_qgesvd)
                      else
                          optwrk = n + max(lwrk_qgeqp3,lwrk_qgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_qgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_qgesvd
                         lwsvd2 = max(5*(n/2),1)
                         lworq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lworq2,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_qgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(5*(n/2),1)
                         lworlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lworlq,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_qgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_qgeqrf(n,n/2,u,ldu,rdummy,rdummy,-1,ierr)
                            lwrk_qgeqrf = int(rdummy(1),KIND=ilp)
                            call la_qgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                       -1,ierr)
                            lwrk_qgesvd2 = int(rdummy(1),KIND=ilp)
                            call la_qormqr('R','C',n,n,n/2,u,ldu,rdummy,v,ldv, &
                                      rdummy,-1,ierr)
                            lwrk_qormqr2 = int(rdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_qgeqp3,n/2 + lwrk_qgeqrf,n/2 + lwrk_qgesvd2,n/2 + &
                                      lwrk_qormqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_qgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_qgelqf(n/2,n,u,ldu,rdummy,rdummy,-1,ierr)
                           lwrk_qgelqf = int(rdummy(1),KIND=ilp)
                           call la_qgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                      -1,ierr)
                           lwrk_qgesvd2 = int(rdummy(1),KIND=ilp)
                           call la_qormlq('R','N',n,n,n/2,u,ldu,rdummy,v,ldv,rdummy, &
                                     -1,ierr)
                           lwrk_qormlq = int(rdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_qgeqp3,n/2 + lwrk_qgelqf,n/2 + lwrk_qgesvd2,n/2 + &
                                     lwrk_qormlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('QGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               work(1) = optwrk
               work(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_qlamch('O')
           ascaled = .false.
           iwoff = 1
           if (rowprm) then
                 iwoff = m
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_izamax(n,a(p,1),lda)) )
                     ! [[la_qlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_qlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('QGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_iqamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_qlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_qlaset('G',m,n,zero,one,u,ldu)
                    if (wntua) call la_qlaset('G',m,m,zero,one,u,ldu)
                    if (wntva) call la_qlaset('G',n,n,zero,one,v,ldv)
                    if (wntuf) then
                        call la_qlaset('G',n,1,zero,zero,work,n)
                        call la_qlaset('G',m,n,zero,one,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=qp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_qlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_qlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_qlange('M',m,n,a,lda,rdummy)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('QGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=qp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_qlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_qgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_qlamch('E')
           sfmin = la_qlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=qp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_qlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_qlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_qnrm2(p,v(1,p),1)
                       call la_qscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_qpocon('U',nr,v,ldv,one,rtmp,work,iwork(n + iwoff),ierr &
                                  )
                    else
                        call la_qpocon('U',nr,v,ldv,one,rtmp,work(n + 1),iwork(n + iwoff), &
                                  ierr)
                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**t = [a](1:nr,1:n)**t
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**t and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    do q = p + 1,n
                       a(q,p) = a(p,q)
                       if (q <= nr) a(p,q) = zero
                    end do
                 end do
                 call la_qgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_qgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_qgesvd to r**t
                  ! .. copy r**t into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_qgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                    end do
              else
                  ! Apply la_qgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_qlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_qgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                     call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_qormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_qgesvd to r**t
                  ! .. copy r**t into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = (a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_qgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_qlaset('G',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                     call la_qgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                               lwork - n,info)
                     do p = 1,n
                        do q = p + 1,n
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                     end do
                     call la_qlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_qgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_qlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_qgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_qlaset('G',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                      call la_qgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                lwork - n,info)
                      call la_qlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the transposed matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_qgesvd to r**t [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite [v], the nr right
                 ! singular vectors of r**t stored in [u](1:nr,1:nr) as transposed
                    call la_qgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                              lwork - n,info)
                    ! Assemble V
                    do p = 1,nr
                       do q = p + 1,nr
                          rtmp = v(q,p)
                          v(q,p) = v(p,q)
                          v(p,q) = rtmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'qgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)

                        call la_qlaset('A',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                        call la_qgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                                  lwork - n,info)
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = v(q,p)
                              v(q,p) = v(p,q)
                              v(p,q) = rtmp
                           end do
                        end do
                        call la_qlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = u(q,p)
                              u(q,p) = u(p,q)
                              u(p,q) = rtmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_qlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_qlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_qlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**t into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,u(1,nr + 2),ldu)

                        call la_qgeqrf(n,nr,u(1,nr + 1),ldu,work(n + 1),work(n + nr + 1),lwork - &
                                  n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = u(p,nr + q)
                            end do
                        end do
                       call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_qgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + 1) &
                                 ,lwork - n - nr,info)
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_qormqr('R','C',n,n,nr,u(1,nr + 1),ldu,work(n + 1),v,ldv,work( &
                                 n + nr + 1),lwork - n - nr,ierr)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_qgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_qlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_qgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'qgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_qlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_qlaset('A',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                       call la_qgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                 lwork - n,info)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the transposed matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_qlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_qlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_qlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_qlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,u(nr + 2,1),ldu)

                       call la_qgelqf(nr,n,u(nr + 1,1),ldu,work(n + 1),work(n + nr + 1),lwork - n - &
                                 nr,ierr)
                       call la_qlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_qgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + &
                                 1),lwork - n - nr,info)
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_qormlq('R','N',n,n,nr,u(nr + 1,1),ldu,work(n + 1),v,ldv,work(n + &
                                 nr + 1),lwork - n - nr,ierr)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**t or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_qormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_qlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_qlascl('G',0,0,one,sqrt(real(m,KIND=qp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_qgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_qgesvdq
#endif

     !> CGESVD: computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, optionally computing the left and/or right singular
     !> vectors. The SVD is written
     !> A = U * SIGMA * conjugate-transpose(V)
     !> where SIGMA is an M-by-N matrix which is zero except for its
     !> min(m,n) diagonal elements, U is an M-by-M unitary matrix, and
     !> V is an N-by-N unitary matrix.  The diagonal elements of SIGMA
     !> are the singular values of A; they are real and non-negative, and
     !> are returned in descending order.  The first min(m,n) columns of
     !> U and V are the left and right singular vectors of A.
     !> Note that the routine returns V**H, not V.

     subroutine la_cgesvd(jobu,jobvt,m,n,a,lda,s,u,ldu,vt,ldvt,work,lwork,rwork, &
               info)
        use la_constants_sp,only:zero,one,czero,cone
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobu,jobvt
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldvt,lwork,m,n
           ! Array Arguments
           real(sp),intent(out) :: rwork(*),s(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wntua,wntuas,wntun,wntuo,wntus,wntva,wntvas,wntvn,wntvo, &
                      wntvs
           integer(ilp) :: blk,chunk,i,ie,ierr,ir,irwork,iscl,itau,itaup,itauq,iu, &
           iwork,ldwrkr,ldwrku,maxwrk,minmn,minwrk,mnthr,ncu,ncvt,nru,nrvt, &
                     wrkbl
           integer(ilp) :: lwork_cgeqrf,lwork_cungqr_n,lwork_cungqr_m,lwork_cgebrd, &
                     lwork_cungbr_p,lwork_cungbr_q,lwork_cgelqf,lwork_cunglq_n,lwork_cunglq_m
           real(sp) :: anrm,bignum,eps,smlnum
           ! Local Arrays
           real(sp) :: dum(1)
           complex(sp) :: cdum(1)
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           wntua = la_lsame(jobu,'A')
           wntus = la_lsame(jobu,'S')
           wntuas = wntua .or. wntus
           wntuo = la_lsame(jobu,'O')
           wntun = la_lsame(jobu,'N')
           wntva = la_lsame(jobvt,'A')
           wntvs = la_lsame(jobvt,'S')
           wntvas = wntva .or. wntvs
           wntvo = la_lsame(jobvt,'O')
           wntvn = la_lsame(jobvt,'N')
           lquery = (lwork == -1)
           if (.not. (wntua .or. wntus .or. wntuo .or. wntun)) then
              info = -1
           else if (.not. (wntva .or. wntvs .or. wntvo .or. wntvn) .or. (wntvo .and. wntuo)) &
                     then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldu < 1 .or. (wntuas .and. ldu < m)) then
              info = -9
           else if (ldvt < 1 .or. (wntva .and. ldvt < n) .or. (wntvs .and. ldvt < minmn)) &
                     then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! cworkspace refers to complex workspace, and rworkspace to
             ! real workspace. nb refers to the optimal block size for the
             ! immediately following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              if (m >= n .and. minmn > 0) then
                 ! space needed for la_zbdsqr is bdspac = 5*n
                 mnthr = la_ilaenv(6,'CGESVD',jobu//jobvt,m,n,0,0)
                 ! compute space needed for la_cgeqrf
                 call la_cgeqrf(m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cgeqrf = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cungqr
                 call la_cungqr(m,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cungqr_n = int(cdum(1),KIND=ilp)
                 call la_cungqr(m,m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cungqr_m = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cgebrd
                 call la_cgebrd(n,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1,ierr)

                 lwork_cgebrd = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cungbr
                 call la_cungbr('P',n,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cungbr_p = int(cdum(1),KIND=ilp)
                 call la_cungbr('Q',n,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cungbr_q = int(cdum(1),KIND=ilp)
                 mnthr = la_ilaenv(6,'CGESVD',jobu//jobvt,m,n,0,0)
                 if (m >= mnthr) then
                    if (wntun) then
                       ! path 1 (m much larger than n, jobu='n')
                       maxwrk = n + lwork_cgeqrf
                       maxwrk = max(maxwrk,2*n + lwork_cgebrd)
                       if (wntvo .or. wntvas) maxwrk = max(maxwrk,2*n + lwork_cungbr_p)
                       minwrk = 3*n
                    else if (wntuo .and. wntvn) then
                       ! path 2 (m much larger than n, jobu='o', jobvt='n')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       maxwrk = max(n*n + wrkbl,n*n + m*n)
                       minwrk = 2*n + m
                    else if (wntuo .and. wntvas) then
                       ! path 3 (m much larger than n, jobu='o', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_p)
                       maxwrk = max(n*n + wrkbl,n*n + m*n)
                       minwrk = 2*n + m
                    else if (wntus .and. wntvn) then
                       ! path 4 (m much larger than n, jobu='s', jobvt='n')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntus .and. wntvo) then
                       ! path 5 (m much larger than n, jobu='s', jobvt='o')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_p)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntus .and. wntvas) then
                       ! path 6 (m much larger than n, jobu='s', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_p)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvn) then
                       ! path 7 (m much larger than n, jobu='a', jobvt='n')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvo) then
                       ! path 8 (m much larger than n, jobu='a', jobvt='o')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_p)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvas) then
                       ! path 9 (m much larger than n, jobu='a', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_cgeqrf
                       wrkbl = max(wrkbl,n + lwork_cungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_cungbr_p)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    end if
                 else
                    ! path 10 (m at least n, but not much larger)
                    call la_cgebrd(m,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1, &
                              ierr)
                    lwork_cgebrd = int(cdum(1),KIND=ilp)
                    maxwrk = 2*n + lwork_cgebrd
                    if (wntus .or. wntuo) then
                       call la_cungbr('Q',m,n,n,a,lda,cdum(1),cdum(1),-1,ierr)

                       lwork_cungbr_q = int(cdum(1),KIND=ilp)
                       maxwrk = max(maxwrk,2*n + lwork_cungbr_q)
                    end if
                    if (wntua) then
                       call la_cungbr('Q',m,m,n,a,lda,cdum(1),cdum(1),-1,ierr)

                       lwork_cungbr_q = int(cdum(1),KIND=ilp)
                       maxwrk = max(maxwrk,2*n + lwork_cungbr_q)
                    end if
                    if (.not. wntvn) then
                       maxwrk = max(maxwrk,2*n + lwork_cungbr_p)
                    end if
                    minwrk = 2*n + m
                 end if
              else if (minmn > 0) then
                 ! space needed for la_cbdsqr is bdspac = 5*m
                 mnthr = la_ilaenv(6,'CGESVD',jobu//jobvt,m,n,0,0)
                 ! compute space needed for la_cgelqf
                 call la_cgelqf(m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cgelqf = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cunglq
                 call la_cunglq(n,n,m,cdum(1),n,cdum(1),cdum(1),-1,ierr)
                 lwork_cunglq_n = int(cdum(1),KIND=ilp)
                 call la_cunglq(m,n,m,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_cunglq_m = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cgebrd
                 call la_cgebrd(m,m,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1,ierr)

                 lwork_cgebrd = int(cdum(1),KIND=ilp)
                  ! compute space needed for la_cungbr p
                 call la_cungbr('P',m,m,m,a,n,cdum(1),cdum(1),-1,ierr)
                 lwork_cungbr_p = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_cungbr q
                 call la_cungbr('Q',m,m,m,a,n,cdum(1),cdum(1),-1,ierr)
                 lwork_cungbr_q = int(cdum(1),KIND=ilp)
                 if (n >= mnthr) then
                    if (wntvn) then
                       ! path 1t(n much larger than m, jobvt='n')
                       maxwrk = m + lwork_cgelqf
                       maxwrk = max(maxwrk,2*m + lwork_cgebrd)
                       if (wntuo .or. wntuas) maxwrk = max(maxwrk,2*m + lwork_cungbr_q)
                       minwrk = 3*m
                    else if (wntvo .and. wntun) then
                       ! path 2t(n much larger than m, jobu='n', jobvt='o')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       maxwrk = max(m*m + wrkbl,m*m + m*n)
                       minwrk = 2*m + n
                    else if (wntvo .and. wntuas) then
                       ! path 3t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='o')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_q)
                       maxwrk = max(m*m + wrkbl,m*m + m*n)
                       minwrk = 2*m + n
                    else if (wntvs .and. wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntvs .and. wntuo) then
                       ! path 5t(n much larger than m, jobu='o', jobvt='s')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_q)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntvs .and. wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='s')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_q)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_q)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='a')
                       wrkbl = m + lwork_cgelqf
                       wrkbl = max(wrkbl,m + lwork_cunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_cgebrd)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_cungbr_q)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    end if
                 else
                    ! path 10t(n greater than m, but not much larger)
                    call la_cgebrd(m,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1, &
                              ierr)
                    lwork_cgebrd = int(cdum(1),KIND=ilp)
                    maxwrk = 2*m + lwork_cgebrd
                    if (wntvs .or. wntvo) then
                      ! compute space needed for la_cungbr p
                      call la_cungbr('P',m,n,m,a,n,cdum(1),cdum(1),-1,ierr)
                      lwork_cungbr_p = int(cdum(1),KIND=ilp)
                      maxwrk = max(maxwrk,2*m + lwork_cungbr_p)
                    end if
                    if (wntva) then
                      call la_cungbr('P',n,n,m,a,n,cdum(1),cdum(1),-1,ierr)
                      lwork_cungbr_p = int(cdum(1),KIND=ilp)
                      maxwrk = max(maxwrk,2*m + lwork_cungbr_p)
                    end if
                    if (.not. wntun) then
                       maxwrk = max(maxwrk,2*m + lwork_cungbr_q)
                    end if
                    minwrk = 2*m + n
                 end if
              end if
              maxwrk = max(minwrk,maxwrk)
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('CGESVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              return
           end if
           ! get machine constants
           eps = la_slamch('P')
           smlnum = sqrt(la_slamch('S'))/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_clange('M',m,n,a,lda,dum)
           iscl = 0
           if (anrm > zero .and. anrm < smlnum) then
              iscl = 1
              call la_clascl('G',0,0,anrm,smlnum,m,n,a,lda,ierr)
           else if (anrm > bignum) then
              iscl = 1
              call la_clascl('G',0,0,anrm,bignum,m,n,a,lda,ierr)
           end if
           if (m >= n) then
              ! a has at least as many rows as columns. if a has sufficiently
              ! more rows than columns, first reduce using the qr
              ! decomposition (if sufficient workspace available)
              if (m >= mnthr) then
                 if (wntun) then
                    ! path 1 (m much larger than n, jobu='n')
                    ! no left singular vectors to be computed
                    itau = 1
                    iwork = itau + n
                    ! compute a=q*r
                    ! (cworkspace: need 2*n, prefer n+n*nb)
                    ! (rworkspace: need 0)
                    call la_cgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out below r
                    if (n > 1) then
                       call la_claset('L',n - 1,n - 1,czero,czero,a(2,1),lda)
                    end if
                    ie = 1
                    itauq = 1
                    itaup = itauq + n
                    iwork = itaup + n
                    ! bidiagonalize r in a
                    ! (cworkspace: need 3*n, prefer 2*n+2*n*nb)
                    ! (rworkspace: need n)
                    call la_cgebrd(n,n,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                               work(iwork),lwork - iwork + 1,ierr)
                    ncvt = 0
                    if (wntvo .or. wntvas) then
                       ! if right singular vectors desired, generate p'.
                       ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                       ! (rworkspace: 0)
                       call la_cungbr('P',n,n,n,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       ncvt = n
                    end if
                    irwork = ie + n
                    ! perform bidiagonal qr iteration, computing right
                    ! singular vectors of a in a if desired
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_cbdsqr('U',n,ncvt,0,0,s,rwork(ie),a,lda,cdum,1,cdum, &
                              1,rwork(irwork),info)
                    ! if right singular vectors desired in vt, copy them there
                    if (wntvas) call la_clacpy('F',n,n,a,lda,vt,ldvt)
                 else if (wntuo .and. wntvn) then
                    ! path 2 (m much larger than n, jobu='o', jobvt='n')
                    ! n left singular vectors to be overwritten on a and
                    ! no right singular vectors to be computed
                    if (lwork >= n*n + 3*n) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n) + lda*n) then
                          ! work(iu) is lda by n, work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n) + n*n) then
                          ! work(iu) is lda by n, work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n, work(ir) is n by n
                          ldwrku = (lwork - n*n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                       ! (rworkspace: 0)
                       call la_cgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to work(ir) and zero out below it
                       call la_clacpy('U',n,n,a,lda,work(ir),ldwrkr)
                       call la_claset('L',n - 1,n - 1,czero,czero,work(ir + 1),ldwrkr)

                       ! generate q in a
