                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in vt
                          ! (cworkspace: need   n*n+3*n-1,
                                       ! prefer n*n+2*n+(n-1)*nb)
                          ! (rworkspace: need   0)
                          call la_zungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                     lwork - iwork + 1,ierr)
                          irwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of r in work(iu) and computing
                          ! right singular vectors of r in vt
                          ! (cworkspace: need n*n)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',n,n,n,0,s,rwork(ie),vt,ldvt,work(iu) &
                                    ,ldwrku,cdum,1,rwork(irwork),info)
                          ! multiply q in u by left singular vectors of r in
                          ! work(iu), storing result in a
                          ! (cworkspace: need n*n)
                          ! (rworkspace: 0)
                          call la_zgemm('N','N',m,n,n,cone,u,ldu,work(iu),ldwrku, &
                                    czero,a,lda)
                          ! copy left singular vectors of a from a to u
                          call la_zlacpy('F',m,n,a,lda,u,ldu)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + n
                          ! compute a=q*r, copying result to u
                          ! (cworkspace: need 2*n, prefer n+n*nb)
                          ! (rworkspace: 0)
                          call la_zgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_zlacpy('L',m,n,a,lda,u,ldu)
                          ! generate q in u
                          ! (cworkspace: need n+m, prefer n+m*nb)
                          ! (rworkspace: 0)
                          call la_zungqr(m,m,n,u,ldu,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy r from a to vt, zeroing out below it
                          call la_zlacpy('U',n,n,a,lda,vt,ldvt)
                          if (n > 1) call la_zlaset('L',n - 1,n - 1,czero,czero,vt(2,1), &
                                    ldvt)
                          ie = 1
                          itauq = itau
                          itaup = itauq + n
                          iwork = itaup + n
                          ! bidiagonalize r in vt
                          ! (cworkspace: need 3*n, prefer 2*n+2*n*nb)
                          ! (rworkspace: need n)
                          call la_zgebrd(n,n,vt,ldvt,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply q in u by left bidiagonalizing vectors
                          ! in vt
                          ! (cworkspace: need 2*n+m, prefer 2*n+m*nb)
                          ! (rworkspace: 0)
                          call la_zunmbr('Q','R','N',m,n,n,vt,ldvt,work(itauq),u, &
                                    ldu,work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in vt
                          ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                     lwork - iwork + 1,ierr)
                          irwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',n,n,m,0,s,rwork(ie),vt,ldvt,u,ldu, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    end if
                 end if
              else
                 ! m < mnthr
                 ! path 10 (m at least n, but not much larger)
                 ! reduce to bidiagonal form without qr decomposition
                 ie = 1
                 itauq = 1
                 itaup = itauq + n
                 iwork = itaup + n
                 ! bidiagonalize a
                 ! (cworkspace: need 2*n+m, prefer 2*n+(m+n)*nb)
                 ! (rworkspace: need n)
                 call la_zgebrd(m,n,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (cworkspace: need 2*n+ncu, prefer 2*n+ncu*nb)
                    ! (rworkspace: 0)
                    call la_zlacpy('L',m,n,a,lda,u,ldu)
                    if (wntus) ncu = n
                    if (wntua) ncu = m
                    call la_zungbr('Q',m,ncu,n,u,ldu,work(itauq),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                    ! (rworkspace: 0)
                    call la_zlacpy('U',n,n,a,lda,vt,ldvt)
                    call la_zungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*n, prefer 2*n+n*nb)
                    ! (rworkspace: 0)
                    call la_zungbr('Q',m,n,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                    ! (rworkspace: 0)
                    call la_zungbr('P',n,n,n,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 irwork = ie + n
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('U',n,ncvt,nru,0,s,rwork(ie),vt,ldvt,u,ldu, &
                              cdum,1,rwork(irwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('U',n,ncvt,nru,0,s,rwork(ie),a,lda,u,ldu,cdum, &
                               1,rwork(irwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('U',n,ncvt,nru,0,s,rwork(ie),vt,ldvt,a,lda, &
                              cdum,1,rwork(irwork),info)
                 end if
              end if
           else
              ! a has more columns than rows. if a has sufficiently more
              ! columns than rows, first reduce using the lq decomposition (if
              ! sufficient workspace available)
              if (n >= mnthr) then
                 if (wntvn) then
                    ! path 1t(n much larger than m, jobvt='n')
                    ! no right singular vectors to be computed
                    itau = 1
                    iwork = itau + m
                    ! compute a=l*q
                    ! (cworkspace: need 2*m, prefer m+m*nb)
                    ! (rworkspace: 0)
                    call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out above l
                    call la_zlaset('U',m - 1,m - 1,czero,czero,a(1,2),lda)
                    ie = 1
                    itauq = 1
                    itaup = itauq + m
                    iwork = itaup + m
                    ! bidiagonalize l in a
                    ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                    ! (rworkspace: need m)
                    call la_zgebrd(m,m,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                               work(iwork),lwork - iwork + 1,ierr)
                    if (wntuo .or. wntuas) then
                       ! if left singular vectors desired, generate q
                       ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                    end if
                    irwork = ie + m
                    nru = 0
                    if (wntuo .or. wntuas) nru = m
                    ! perform bidiagonal qr iteration, computing left singular
                    ! vectors of a in a if desired
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('U',m,0,nru,0,s,rwork(ie),cdum,1,a,lda,cdum, &
                              1,rwork(irwork),info)
                    ! if left singular vectors desired in u, copy them there
                    if (wntuas) call la_zlacpy('F',m,m,a,lda,u,ldu)
                 else if (wntvo .and. wntun) then
                    ! path 2t(n much larger than m, jobu='n', jobvt='o')
                    ! m right singular vectors to be overwritten on a and
                    ! no left singular vectors to be computed
                    if (lwork >= m*m + 3*m) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n) + lda*m) then
                          ! work(iu) is lda by n and work(ir) is lda by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n) + m*m) then
                          ! work(iu) is lda by n and work(ir) is m by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = m
                       else
                          ! work(iu) is m by chunk and work(ir) is m by m
                          ldwrku = m
                          chunk = (lwork - m*m)/m
                          ldwrkr = m
                       end if
                       itau = ir + ldwrkr*m
                       iwork = itau + m
                       ! compute a=l*q
                       ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                       ! (rworkspace: 0)
                       call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to work(ir) and zero out above it
                       call la_zlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                       call la_zlaset('U',m - 1,m - 1,czero,czero,work(ir + ldwrkr),ldwrkr)

                       ! generate q in a
                       ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                       ! (rworkspace: 0)
                       call la_zunglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in work(ir)
                       ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                       ! (rworkspace: need m)
                       call la_zgebrd(m,m,work(ir),ldwrkr,s,rwork(ie),work(itauq), &
                                  work(itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing l
                       ! (cworkspace: need m*m+3*m-1, prefer m*m+2*m+(m-1)*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('P',m,m,m,work(ir),ldwrkr,work(itaup),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       irwork = ie + m
                       ! perform bidiagonal qr iteration, computing right
                       ! singular vectors of l in work(ir)
                       ! (cworkspace: need m*m)
                       ! (rworkspace: need bdspac)
                       call la_zbdsqr('U',m,m,0,0,s,rwork(ie),work(ir),ldwrkr, &
                                 cdum,1,cdum,1,rwork(irwork),info)
                       iu = itauq
                       ! multiply right singular vectors of l in work(ir) by q
                       ! in a, storing result in work(iu) and copying to a
                       ! (cworkspace: need m*m+m, prefer m*m+m*n)
                       ! (rworkspace: 0)
                       do i = 1,n,chunk
                          blk = min(n - i + 1,chunk)
                          call la_zgemm('N','N',m,blk,m,cone,work(ir),ldwrkr,a(1, &
                                    i),lda,czero,work(iu),ldwrku)
                          call la_zlacpy('F',m,blk,work(iu),ldwrku,a(1,i),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       ie = 1
                       itauq = 1
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize a
                       ! (cworkspace: need 2*m+n, prefer 2*m+(m+n)*nb)
                       ! (rworkspace: need m)
                       call la_zgebrd(m,n,a,lda,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing a
                       ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('P',m,n,m,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + m
                       ! perform bidiagonal qr iteration, computing right
                       ! singular vectors of a in a
                       ! (cworkspace: 0)
                       ! (rworkspace: need bdspac)
                       call la_zbdsqr('L',m,n,0,0,s,rwork(ie),a,lda,cdum,1,cdum, &
                                 1,rwork(irwork),info)
                    end if
                 else if (wntvo .and. wntuas) then
                    ! path 3t(n much larger than m, jobu='s' or 'a', jobvt='o')
                    ! m right singular vectors to be overwritten on a and
                    ! m left singular vectors to be computed in u
                    if (lwork >= m*m + 3*m) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n) + lda*m) then
                          ! work(iu) is lda by n and work(ir) is lda by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n) + m*m) then
                          ! work(iu) is lda by n and work(ir) is m by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = m
                       else
                          ! work(iu) is m by chunk and work(ir) is m by m
                          ldwrku = m
                          chunk = (lwork - m*m)/m
                          ldwrkr = m
                       end if
                       itau = ir + ldwrkr*m
                       iwork = itau + m
                       ! compute a=l*q
                       ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                       ! (rworkspace: 0)
                       call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to u, zeroing about above it
                       call la_zlacpy('L',m,m,a,lda,u,ldu)
                       call la_zlaset('U',m - 1,m - 1,czero,czero,u(1,2),ldu)
                       ! generate q in a
                       ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                       ! (rworkspace: 0)
                       call la_zunglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in u, copying result to work(ir)
                       ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                       ! (rworkspace: need m)
                       call la_zgebrd(m,m,u,ldu,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       call la_zlacpy('U',m,m,u,ldu,work(ir),ldwrkr)
                       ! generate right vectors bidiagonalizing l in work(ir)
                       ! (cworkspace: need m*m+3*m-1, prefer m*m+2*m+(m-1)*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('P',m,m,m,work(ir),ldwrkr,work(itaup),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing l in u
                       ! (cworkspace: need m*m+3*m, prefer m*m+2*m+m*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + m
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of l in u, and computing right
                       ! singular vectors of l in work(ir)
                       ! (cworkspace: need m*m)
                       ! (rworkspace: need bdspac)
                       call la_zbdsqr('U',m,m,m,0,s,rwork(ie),work(ir),ldwrkr,u, &
                                 ldu,cdum,1,rwork(irwork),info)
                       iu = itauq
                       ! multiply right singular vectors of l in work(ir) by q
                       ! in a, storing result in work(iu) and copying to a
                       ! (cworkspace: need m*m+m, prefer m*m+m*n))
                       ! (rworkspace: 0)
                       do i = 1,n,chunk
                          blk = min(n - i + 1,chunk)
                          call la_zgemm('N','N',m,blk,m,cone,work(ir),ldwrkr,a(1, &
                                    i),lda,czero,work(iu),ldwrku)
                          call la_zlacpy('F',m,blk,work(iu),ldwrku,a(1,i),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       itau = 1
                       iwork = itau + m
                       ! compute a=l*q
                       ! (cworkspace: need 2*m, prefer m+m*nb)
                       ! (rworkspace: 0)
                       call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to u, zeroing out above it
                       call la_zlacpy('L',m,m,a,lda,u,ldu)
                       call la_zlaset('U',m - 1,m - 1,czero,czero,u(1,2),ldu)
                       ! generate q in a
                       ! (cworkspace: need 2*m, prefer m+m*nb)
                       ! (rworkspace: 0)
                       call la_zunglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in u
                       ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                       ! (rworkspace: need m)
                       call la_zgebrd(m,m,u,ldu,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! multiply right vectors bidiagonalizing l by q in a
                       ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                       ! (rworkspace: 0)
                       call la_zunmbr('P','L','C',m,n,m,u,ldu,work(itaup),a,lda, &
                                 work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing l in u
                       ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                       ! (rworkspace: 0)
                       call la_zungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + m
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of a in u and computing right
                       ! singular vectors of a in a
                       ! (cworkspace: 0)
                       ! (rworkspace: need bdspac)
                       call la_zbdsqr('U',m,n,m,0,s,rwork(ie),a,lda,u,ldu,cdum, &
                                 1,rwork(irwork),info)
                    end if
                 else if (wntvs) then
                    if (wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! no left singular vectors to be computed
                       if (lwork >= m*m + 3*m) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(ir) is lda by m
                             ldwrkr = lda
                          else
                             ! work(ir) is m by m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(ir), zeroing out above it
                          call la_zlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_zlaset('U',m - 1,m - 1,czero,czero,work(ir + ldwrkr), &
                                    ldwrkr)
                          ! generate q in a
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_zunglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_zgebrd(m,m,work(ir),ldwrkr,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right vectors bidiagonalizing l in
                          ! work(ir)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',m,m,0,0,s,rwork(ie),work(ir),ldwrkr, &
                                    cdum,1,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in a, storing result in vt
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_zgemm('N','N',m,n,m,cone,work(ir),ldwrkr,a,lda, &
                                    czero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy result to vt
                          call la_zlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
