                          ! (rworkspace: need   m)
                          call la_zgebrd(m,m,work(iu),ldwrku,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_zlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

