                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_zlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m+n, prefer m+n*nb)
                          ! (rworkspace: 0)
                          call la_zunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_zlaset('U',m - 1,m - 1,czero,czero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_zgebrd(m,m,a,lda,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_zunmbr('P','L','C',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in a
                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in a and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',m,n,m,0,s,rwork(ie),vt,ldvt,a,lda, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    else if (wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(n + m,3*m)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by m
                             ldwrku = lda
                          else
                             ! work(iu) is m by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_zlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m*m+m+n, prefer m*m+m+n*nb)
                          ! (rworkspace: 0)
                          call la_zunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_zlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_zlaset('U',m - 1,m - 1,czero,czero,work(iu + ldwrku), &
                                    ldwrku)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_zgebrd(m,m,work(iu),ldwrku,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_zlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',m,m,m,0,s,rwork(ie),work(iu),ldwrku, &
                                    u,ldu,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_zgemm('N','N',m,n,m,cone,work(iu),ldwrku,vt,ldvt, &
                                     czero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_zlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_zgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_zlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m+n, prefer m+n*nb)
                          ! (rworkspace: 0)
                          call la_zunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_zlacpy('L',m,m,a,lda,u,ldu)
                          call la_zlaset('U',m - 1,m - 1,czero,czero,u(1,2),ldu)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_zgebrd(m,m,u,ldu,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_zunmbr('P','L','C',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_zungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_zbdsqr('U',m,n,m,0,s,rwork(ie),vt,ldvt,u,ldu, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    end if
                 end if
              else
                 ! n < mnthr
                 ! path 10t(n greater than m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = 1
                 itaup = itauq + m
                 iwork = itaup + m
                 ! bidiagonalize a
                 ! (cworkspace: need 2*m+n, prefer 2*m+(m+n)*nb)
                 ! (rworkspace: m)
                 call la_zgebrd(m,n,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (cworkspace: need 3*m-1, prefer 2*m+(m-1)*nb)
                    ! (rworkspace: 0)
                    call la_zlacpy('L',m,m,a,lda,u,ldu)
                    call la_zungbr('Q',m,m,n,u,ldu,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (cworkspace: need 2*m+nrvt, prefer 2*m+nrvt*nb)
                    ! (rworkspace: 0)
                    call la_zlacpy('U',m,n,a,lda,vt,ldvt)
                    if (wntva) nrvt = n
                    if (wntvs) nrvt = m
                    call la_zungbr('P',nrvt,n,m,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*m-1, prefer 2*m+(m-1)*nb)
                    ! (rworkspace: 0)
                    call la_zungbr('Q',m,m,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                    ! (rworkspace: 0)
                    call la_zungbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 irwork = ie + m
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('L',m,ncvt,nru,0,s,rwork(ie),vt,ldvt,u,ldu, &
                              cdum,1,rwork(irwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('L',m,ncvt,nru,0,s,rwork(ie),a,lda,u,ldu,cdum, &
                               1,rwork(irwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_zbdsqr('L',m,ncvt,nru,0,s,rwork(ie),vt,ldvt,a,lda, &
                              cdum,1,rwork(irwork),info)
                 end if
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_dlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm > bignum) call la_dlascl('G',0,0,bignum,anrm,minmn - 1, &
                         1,rwork(ie),minmn,ierr)
              if (anrm < smlnum) call la_dlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm < smlnum) call la_dlascl('G',0,0,smlnum,anrm,minmn - 1, &
                         1,rwork(ie),minmn,ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = maxwrk
           return
     end subroutine la_zgesvd
#ifdef LA_WITH_XDP
     !> YGESVD: computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, optionally computing the left and/or right singular
     !> vectors. The SVD is written
     !> A = U * SIGMA * conjugate-transpose(V)
     !> where SIGMA is an M-by-N matrix which is zero except for its
     !> min(m,n) diagonal elements, U is an M-by-M unitary matrix, and
     !> V is an N-by-N unitary matrix.  The diagonal elements of SIGMA
     !> are the singular values of A; they are real and non-negative, and
     !> are returned in descending order.  The first min(m,n) columns of
     !> U and V are the left and right singular vectors of A.
     !> Note that the routine returns V**H, not V.

     subroutine la_ygesvd(jobu,jobvt,m,n,a,lda,s,u,ldu,vt,ldvt,work,lwork,rwork, &
               info)
        use la_constants_xdp,only:zero,one,czero,cone
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobu,jobvt
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldvt,lwork,m,n
           ! Array Arguments
           real(xdp),intent(out) :: rwork(*),s(*)
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wntua,wntuas,wntun,wntuo,wntus,wntva,wntvas,wntvn,wntvo, &
                      wntvs
           integer(ilp) :: blk,chunk,i,ie,ierr,ir,irwork,iscl,itau,itaup,itauq,iu, &
           iwork,ldwrkr,ldwrku,maxwrk,minmn,minwrk,mnthr,ncu,ncvt,nru,nrvt, &
                     wrkbl
           integer(ilp) :: lwork_ygeqrf,lwork_yungqr_n,lwork_yungqr_m,lwork_ygebrd, &
                     lwork_yungbr_p,lwork_yungbr_q,lwork_ygelqf,lwork_yunglq_n,lwork_yunglq_m
           real(xdp) :: anrm,bignum,eps,smlnum
           ! Local Arrays
           real(xdp) :: dum(1)
           complex(xdp) :: cdum(1)
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           wntua = la_lsame(jobu,'A')
           wntus = la_lsame(jobu,'S')
           wntuas = wntua .or. wntus
           wntuo = la_lsame(jobu,'O')
           wntun = la_lsame(jobu,'N')
           wntva = la_lsame(jobvt,'A')
           wntvs = la_lsame(jobvt,'S')
           wntvas = wntva .or. wntvs
           wntvo = la_lsame(jobvt,'O')
           wntvn = la_lsame(jobvt,'N')
           lquery = (lwork == -1)
           if (.not. (wntua .or. wntus .or. wntuo .or. wntun)) then
              info = -1
           else if (.not. (wntva .or. wntvs .or. wntvo .or. wntvn) .or. (wntvo .and. wntuo)) &
                     then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldu < 1 .or. (wntuas .and. ldu < m)) then
              info = -9
           else if (ldvt < 1 .or. (wntva .and. ldvt < n) .or. (wntvs .and. ldvt < minmn)) &
                     then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! cworkspace refers to complex workspace, and rworkspace to
             ! real workspace. nb refers to the optimal block size for the
             ! immediately following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              if (m >= n .and. minmn > 0) then
                 ! space needed for la_ybdsqr is bdspac = 5*n
                 mnthr = la_ilaenv(6,'YGESVD',jobu//jobvt,m,n,0,0)
                 ! compute space needed for la_ygeqrf
                 call la_ygeqrf(m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_ygeqrf = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_yungqr
                 call la_yungqr(m,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_yungqr_n = int(cdum(1),KIND=ilp)
                 call la_yungqr(m,m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_yungqr_m = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_ygebrd
                 call la_ygebrd(n,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1,ierr)

                 lwork_ygebrd = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_yungbr
                 call la_yungbr('P',n,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_yungbr_p = int(cdum(1),KIND=ilp)
                 call la_yungbr('Q',n,n,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_yungbr_q = int(cdum(1),KIND=ilp)
                 if (m >= mnthr) then
                    if (wntun) then
                       ! path 1 (m much larger than n, jobu='n')
                       maxwrk = n + lwork_ygeqrf
                       maxwrk = max(maxwrk,2*n + lwork_ygebrd)
                       if (wntvo .or. wntvas) maxwrk = max(maxwrk,2*n + lwork_yungbr_p)
                       minwrk = 3*n
                    else if (wntuo .and. wntvn) then
                       ! path 2 (m much larger than n, jobu='o', jobvt='n')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       maxwrk = max(n*n + wrkbl,n*n + m*n)
                       minwrk = 2*n + m
                    else if (wntuo .and. wntvas) then
                       ! path 3 (m much larger than n, jobu='o', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_p)
                       maxwrk = max(n*n + wrkbl,n*n + m*n)
                       minwrk = 2*n + m
                    else if (wntus .and. wntvn) then
                       ! path 4 (m much larger than n, jobu='s', jobvt='n')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntus .and. wntvo) then
                       ! path 5 (m much larger than n, jobu='s', jobvt='o')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_p)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntus .and. wntvas) then
                       ! path 6 (m much larger than n, jobu='s', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_n)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_p)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvn) then
                       ! path 7 (m much larger than n, jobu='a', jobvt='n')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvo) then
                       ! path 8 (m much larger than n, jobu='a', jobvt='o')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_p)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = 2*n + m
                    else if (wntua .and. wntvas) then
                       ! path 9 (m much larger than n, jobu='a', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_ygeqrf
                       wrkbl = max(wrkbl,n + lwork_yungqr_m)
                       wrkbl = max(wrkbl,2*n + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_q)
                       wrkbl = max(wrkbl,2*n + lwork_yungbr_p)
                       maxwrk = n*n + wrkbl
                       minwrk = 2*n + m
                    end if
                 else
                    ! path 10 (m at least n, but not much larger)
                    call la_ygebrd(m,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1, &
                              ierr)
                    lwork_ygebrd = int(cdum(1),KIND=ilp)
                    maxwrk = 2*n + lwork_ygebrd
                    if (wntus .or. wntuo) then
                       call la_yungbr('Q',m,n,n,a,lda,cdum(1),cdum(1),-1,ierr)

                       lwork_yungbr_q = int(cdum(1),KIND=ilp)
                       maxwrk = max(maxwrk,2*n + lwork_yungbr_q)
                    end if
                    if (wntua) then
                       call la_yungbr('Q',m,m,n,a,lda,cdum(1),cdum(1),-1,ierr)

                       lwork_yungbr_q = int(cdum(1),KIND=ilp)
                       maxwrk = max(maxwrk,2*n + lwork_yungbr_q)
                    end if
                    if (.not. wntvn) then
                       maxwrk = max(maxwrk,2*n + lwork_yungbr_p)
                    end if
                    minwrk = 2*n + m
                 end if
              else if (minmn > 0) then
                 ! space needed for la_ybdsqr is bdspac = 5*m
                 mnthr = la_ilaenv(6,'YGESVD',jobu//jobvt,m,n,0,0)
                 ! compute space needed for la_ygelqf
                 call la_ygelqf(m,n,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_ygelqf = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_yunglq
                 call la_yunglq(n,n,m,cdum(1),n,cdum(1),cdum(1),-1,ierr)
                 lwork_yunglq_n = int(cdum(1),KIND=ilp)
                 call la_yunglq(m,n,m,a,lda,cdum(1),cdum(1),-1,ierr)
                 lwork_yunglq_m = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_ygebrd
                 call la_ygebrd(m,m,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1,ierr)

                 lwork_ygebrd = int(cdum(1),KIND=ilp)
                  ! compute space needed for la_yungbr p
                 call la_yungbr('P',m,m,m,a,n,cdum(1),cdum(1),-1,ierr)
                 lwork_yungbr_p = int(cdum(1),KIND=ilp)
                 ! compute space needed for la_yungbr q
                 call la_yungbr('Q',m,m,m,a,n,cdum(1),cdum(1),-1,ierr)
                 lwork_yungbr_q = int(cdum(1),KIND=ilp)
                 if (n >= mnthr) then
                    if (wntvn) then
                       ! path 1t(n much larger than m, jobvt='n')
                       maxwrk = m + lwork_ygelqf
                       maxwrk = max(maxwrk,2*m + lwork_ygebrd)
                       if (wntuo .or. wntuas) maxwrk = max(maxwrk,2*m + lwork_yungbr_q)
                       minwrk = 3*m
                    else if (wntvo .and. wntun) then
                       ! path 2t(n much larger than m, jobu='n', jobvt='o')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       maxwrk = max(m*m + wrkbl,m*m + m*n)
                       minwrk = 2*m + n
                    else if (wntvo .and. wntuas) then
                       ! path 3t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='o')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_q)
                       maxwrk = max(m*m + wrkbl,m*m + m*n)
                       minwrk = 2*m + n
                    else if (wntvs .and. wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntvs .and. wntuo) then
                       ! path 5t(n much larger than m, jobu='o', jobvt='s')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_q)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntvs .and. wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='s')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_m)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_q)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_q)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = 2*m + n
                    else if (wntva .and. wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='a')
                       wrkbl = m + lwork_ygelqf
                       wrkbl = max(wrkbl,m + lwork_yunglq_n)
                       wrkbl = max(wrkbl,2*m + lwork_ygebrd)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_p)
                       wrkbl = max(wrkbl,2*m + lwork_yungbr_q)
                       maxwrk = m*m + wrkbl
                       minwrk = 2*m + n
                    end if
                 else
                    ! path 10t(n greater than m, but not much larger)
                    call la_ygebrd(m,n,a,lda,s,dum(1),cdum(1),cdum(1),cdum(1),-1, &
                              ierr)
                    lwork_ygebrd = int(cdum(1),KIND=ilp)
                    maxwrk = 2*m + lwork_ygebrd
                    if (wntvs .or. wntvo) then
                      ! compute space needed for la_yungbr p
                      call la_yungbr('P',m,n,m,a,n,cdum(1),cdum(1),-1,ierr)
                      lwork_yungbr_p = int(cdum(1),KIND=ilp)
                      maxwrk = max(maxwrk,2*m + lwork_yungbr_p)
                    end if
                    if (wntva) then
                      call la_yungbr('P',n,n,m,a,n,cdum(1),cdum(1),-1,ierr)
                      lwork_yungbr_p = int(cdum(1),KIND=ilp)
                      maxwrk = max(maxwrk,2*m + lwork_yungbr_p)
                    end if
                    if (.not. wntun) then
                       maxwrk = max(maxwrk,2*m + lwork_yungbr_q)
                    end if
                    minwrk = 2*m + n
                 end if
              end if
              maxwrk = max(maxwrk,minwrk)
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('YGESVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              return
           end if
           ! get machine constants
           eps = la_xlamch('P')
           smlnum = sqrt(la_xlamch('S'))/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_ylange('M',m,n,a,lda,dum)
           iscl = 0
           if (anrm > zero .and. anrm < smlnum) then
              iscl = 1
              call la_ylascl('G',0,0,anrm,smlnum,m,n,a,lda,ierr)
           else if (anrm > bignum) then
              iscl = 1
              call la_ylascl('G',0,0,anrm,bignum,m,n,a,lda,ierr)
           end if
           if (m >= n) then
              ! a has at least as many rows as columns. if a has sufficiently
              ! more rows than columns, first reduce using the qr
              ! decomposition (if sufficient workspace available)
              if (m >= mnthr) then
                 if (wntun) then
                    ! path 1 (m much larger than n, jobu='n')
                    ! no left singular vectors to be computed
                    itau = 1
                    iwork = itau + n
                    ! compute a=q*r
                    ! (cworkspace: need 2*n, prefer n+n*nb)
                    ! (rworkspace: need 0)
                    call la_ygeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out below r
                    if (n > 1) then
                       call la_ylaset('L',n - 1,n - 1,czero,czero,a(2,1),lda)
                    end if
                    ie = 1
                    itauq = 1
                    itaup = itauq + n
                    iwork = itaup + n
                    ! bidiagonalize r in a
                    ! (cworkspace: need 3*n, prefer 2*n+2*n*nb)
                    ! (rworkspace: need n)
                    call la_ygebrd(n,n,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                               work(iwork),lwork - iwork + 1,ierr)
                    ncvt = 0
                    if (wntvo .or. wntvas) then
                       ! if right singular vectors desired, generate p'.
                       ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                       ! (rworkspace: 0)
                       call la_yungbr('P',n,n,n,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       ncvt = n
                    end if
                    irwork = ie + n
                    ! perform bidiagonal qr iteration, computing right
                    ! singular vectors of a in a if desired
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_ybdsqr('U',n,ncvt,0,0,s,rwork(ie),a,lda,cdum,1,cdum, &
                              1,rwork(irwork),info)
                    ! if right singular vectors desired in vt, copy them there
                    if (wntvas) call la_ylacpy('F',n,n,a,lda,vt,ldvt)
                 else if (wntuo .and. wntvn) then
                    ! path 2 (m much larger than n, jobu='o', jobvt='n')
                    ! n left singular vectors to be overwritten on a and
                    ! no right singular vectors to be computed
                    if (lwork >= n*n + 3*n) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n) + lda*n) then
                          ! work(iu) is lda by n, work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n) + n*n) then
                          ! work(iu) is lda by n, work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n, work(ir) is n by n
                          ldwrku = (lwork - n*n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                       ! (rworkspace: 0)
                       call la_ygeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to work(ir) and zero out below it
                       call la_ylacpy('U',n,n,a,lda,work(ir),ldwrkr)
                       call la_ylaset('L',n - 1,n - 1,czero,czero,work(ir + 1),ldwrkr)

                       ! generate q in a
                       ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                       ! (rworkspace: 0)
                       call la_yungqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in work(ir)
                       ! (cworkspace: need n*n+3*n, prefer n*n+2*n+2*n*nb)
                       ! (rworkspace: need n)
                       call la_ygebrd(n,n,work(ir),ldwrkr,s,rwork(ie),work(itauq), &
                                  work(itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing r
                       ! (cworkspace: need n*n+3*n, prefer n*n+2*n+n*nb)
                       ! (rworkspace: need 0)
                       call la_yungbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       irwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of r in work(ir)
                       ! (cworkspace: need n*n)
                       ! (rworkspace: need bdspac)
                       call la_ybdsqr('U',n,0,n,0,s,rwork(ie),cdum,1,work(ir), &
                                 ldwrkr,cdum,1,rwork(irwork),info)
                       iu = itauq
                       ! multiply q in a by left singular vectors of r in
                       ! work(ir), storing result in work(iu) and copying to a
                       ! (cworkspace: need n*n+n, prefer n*n+m*n)
                       ! (rworkspace: 0)
                       do i = 1,m,ldwrku
                          chunk = min(m - i + 1,ldwrku)
                          call la_ygemm('N','N',chunk,n,n,cone,a(i,1),lda,work(ir &
                                    ),ldwrkr,czero,work(iu),ldwrku)
                          call la_ylacpy('F',chunk,n,work(iu),ldwrku,a(i,1),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       ie = 1
                       itauq = 1
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize a
                       ! (cworkspace: need 2*n+m, prefer 2*n+(m+n)*nb)
                       ! (rworkspace: n)
                       call la_ygebrd(m,n,a,lda,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing a
                       ! (cworkspace: need 3*n, prefer 2*n+n*nb)
                       ! (rworkspace: 0)
                       call la_yungbr('Q',m,n,n,a,lda,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of a in a
                       ! (cworkspace: need 0)
                       ! (rworkspace: need bdspac)
                       call la_ybdsqr('U',n,0,m,0,s,rwork(ie),cdum,1,a,lda,cdum, &
                                 1,rwork(irwork),info)
                    end if
                 else if (wntuo .and. wntvas) then
                    ! path 3 (m much larger than n, jobu='o', jobvt='s' or 'a')
                    ! n left singular vectors to be overwritten on a and
                    ! n right singular vectors to be computed in vt
                    if (lwork >= n*n + 3*n) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n) + lda*n) then
                          ! work(iu) is lda by n and work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n) + n*n) then
                          ! work(iu) is lda by n and work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n and work(ir) is n by n
                          ldwrku = (lwork - n*n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                       ! (rworkspace: 0)
                       call la_ygeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to vt, zeroing out below it
                       call la_ylacpy('U',n,n,a,lda,vt,ldvt)
                       if (n > 1) call la_ylaset('L',n - 1,n - 1,czero,czero,vt(2,1),ldvt)

                       ! generate q in a
                       ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                       ! (rworkspace: 0)
                       call la_yungqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in vt, copying result to work(ir)
                       ! (cworkspace: need n*n+3*n, prefer n*n+2*n+2*n*nb)
                       ! (rworkspace: need n)
                       call la_ygebrd(n,n,vt,ldvt,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       call la_ylacpy('L',n,n,vt,ldvt,work(ir),ldwrkr)
                       ! generate left vectors bidiagonalizing r in work(ir)
                       ! (cworkspace: need n*n+3*n, prefer n*n+2*n+n*nb)
                       ! (rworkspace: 0)
                       call la_yungbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing r in vt
                       ! (cworkspace: need n*n+3*n-1, prefer n*n+2*n+(n-1)*nb)
                       ! (rworkspace: 0)
                       call la_yungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of r in work(ir) and computing right
                       ! singular vectors of r in vt
                       ! (cworkspace: need n*n)
                       ! (rworkspace: need bdspac)
                       call la_ybdsqr('U',n,n,n,0,s,rwork(ie),vt,ldvt,work(ir), &
                                 ldwrkr,cdum,1,rwork(irwork),info)
                       iu = itauq
                       ! multiply q in a by left singular vectors of r in
                       ! work(ir), storing result in work(iu) and copying to a
                       ! (cworkspace: need n*n+n, prefer n*n+m*n)
                       ! (rworkspace: 0)
                       do i = 1,m,ldwrku
                          chunk = min(m - i + 1,ldwrku)
                          call la_ygemm('N','N',chunk,n,n,cone,a(i,1),lda,work(ir &
                                    ),ldwrkr,czero,work(iu),ldwrku)
                          call la_ylacpy('F',chunk,n,work(iu),ldwrku,a(i,1),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       itau = 1
                       iwork = itau + n
                       ! compute a=q*r
                       ! (cworkspace: need 2*n, prefer n+n*nb)
                       ! (rworkspace: 0)
                       call la_ygeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to vt, zeroing out below it
                       call la_ylacpy('U',n,n,a,lda,vt,ldvt)
                       if (n > 1) call la_ylaset('L',n - 1,n - 1,czero,czero,vt(2,1),ldvt)

                       ! generate q in a
                       ! (cworkspace: need 2*n, prefer n+n*nb)
                       ! (rworkspace: 0)
                       call la_yungqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = 1
                       itauq = itau
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in vt
                       ! (cworkspace: need 3*n, prefer 2*n+2*n*nb)
                       ! (rworkspace: n)
                       call la_ygebrd(n,n,vt,ldvt,s,rwork(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! multiply q in a by left vectors bidiagonalizing r
                       ! (cworkspace: need 2*n+m, prefer 2*n+m*nb)
                       ! (rworkspace: 0)
                       call la_yunmbr('Q','R','N',m,n,n,vt,ldvt,work(itauq),a,lda, &
                                  work(iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing r in vt
                       ! (cworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
                       ! (rworkspace: 0)
                       call la_yungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of a in a and computing right
                       ! singular vectors of a in vt
                       ! (cworkspace: 0)
                       ! (rworkspace: need bdspac)
                       call la_ybdsqr('U',n,n,m,0,s,rwork(ie),vt,ldvt,a,lda,cdum, &
                                  1,rwork(irwork),info)
                    end if
                 else if (wntus) then
                    if (wntvn) then
                       ! path 4 (m much larger than n, jobu='s', jobvt='n')
                       ! n left singular vectors to be computed in u and
                       ! no right singular vectors to be computed
                       if (lwork >= n*n + 3*n) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*n) then
                             ! work(ir) is lda by n
                             ldwrkr = lda
                          else
                             ! work(ir) is n by n
                             ldwrkr = n
                          end if
                          itau = ir + ldwrkr*n
                          iwork = itau + n
                          ! compute a=q*r
                          ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                          ! (rworkspace: 0)
                          call la_ygeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy r to work(ir), zeroing out below it
                          call la_ylacpy('U',n,n,a,lda,work(ir),ldwrkr)
                          call la_ylaset('L',n - 1,n - 1,czero,czero,work(ir + 1),ldwrkr)

                          ! generate q in a
                          ! (cworkspace: need n*n+2*n, prefer n*n+n+n*nb)
                          ! (rworkspace: 0)
                          call la_yungqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + n
                          iwork = itaup + n
                          ! bidiagonalize r in work(ir)
                          ! (cworkspace: need n*n+3*n, prefer n*n+2*n+2*n*nb)
                          ! (rworkspace: need n)
                          call la_ygebrd(n,n,work(ir),ldwrkr,s,rwork(ie),work( &
