                       ! (cworkspace: need n*n+3*n-1, prefer n*n+2*n+(n-1)*nb)
                       ! (rworkspace: 0)
                       call la_wungbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       irwork = ie + n
