                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(ir), zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,work(ir + ldwrkr), &
                                    ldwrkr)
                          ! generate q in a
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,work(ir),ldwrkr,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right vectors bidiagonalizing l in
                          ! work(ir)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,m,0,0,s,rwork(ie),work(ir),ldwrkr, &
                                    cdum,1,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in a, storing result in vt
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_wgemm('N','N',m,n,m,cone,work(ir),ldwrkr,a,lda, &
                                    czero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy result to vt
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
