                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
