                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by n
                             ldwrku = lda
                          else
                             ! work(iu) is lda by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
