                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,m,m,0,s,rwork(ie),work(iu),ldwrku, &
                                    u,ldu,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in a, storing result in vt
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_wgemm('N','N',m,n,m,cone,work(iu),ldwrku,a,lda, &
                                    czero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,u,ldu)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,u(1,2),ldu)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,u,ldu,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunmbr('P','L','C',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,n,m,0,s,rwork(ie),vt,ldvt,u,ldu, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    end if
                 else if (wntva) then
                    if (wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! no left singular vectors to be computed
                       if (lwork >= m*m + max(n + m,3*m)) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(ir) is lda by m
                             ldwrkr = lda
                          else
                             ! work(ir) is m by m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! copy l to work(ir), zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,work(ir + ldwrkr), &
                                    ldwrkr)
                          ! generate q in vt
                          ! (cworkspace: need m*m+m+n, prefer m*m+m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,work(ir),ldwrkr,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in work(ir)
                          ! (cworkspace: need   m*m+3*m-1,
                                       ! prefer m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,m,0,0,s,rwork(ie),work(ir),ldwrkr, &
                                    cdum,1,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in vt, storing result in a
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_wgemm('N','N',m,n,m,cone,work(ir),ldwrkr,vt,ldvt, &
                                     czero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_wlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m+n, prefer m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_wlaset('U',m - 1,m - 1,czero,czero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,a,lda,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunmbr('P','L','C',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,n,0,0,s,rwork(ie),vt,ldvt,cdum,1, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    else if (wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be overwritten on a
                       if (lwork >= 2*m*m + max(n + m,3*m)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*m) then
                             ! work(iu) is lda by m and work(ir) is lda by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + m)*m) then
                             ! work(iu) is lda by m and work(ir) is m by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          else
                             ! work(iu) is m by m and work(ir) is m by m
                             ldwrku = m
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m*m+2*m, prefer 2*m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need 2*m*m+m+n, prefer 2*m*m+m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,work(iu + ldwrku), &
                                    ldwrku)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to
                          ! work(ir)
                          ! (cworkspace: need   2*m*m+3*m,
                                       ! prefer 2*m*m+2*m+2*m*nb)
                          ! (rworkspace: need   m)
                          call la_wgebrd(m,m,work(iu),ldwrku,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_wlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (cworkspace: need   2*m*m+3*m-1,
                                       ! prefer 2*m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in work(ir)
                          ! (cworkspace: need 2*m*m+3*m, prefer 2*m*m+2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,work(ir),ldwrkr,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in work(ir) and computing
                          ! right singular vectors of l in work(iu)
                          ! (cworkspace: need 2*m*m)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,m,m,0,s,rwork(ie),work(iu),ldwrku, &
                                    work(ir),ldwrkr,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_wgemm('N','N',m,n,m,cone,work(iu),ldwrku,vt,ldvt, &
                                     czero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_wlacpy('F',m,n,a,lda,vt,ldvt)
                          ! copy left singular vectors of a from work(ir) to a
                          call la_wlacpy('F',m,m,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m+n, prefer m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_wlaset('U',m - 1,m - 1,czero,czero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,a,lda,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunmbr('P','L','C',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in a
                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in a and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,n,m,0,s,rwork(ie),vt,ldvt,a,lda, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    else if (wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(n + m,3*m)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by m
                             ldwrku = lda
                          else
                             ! work(iu) is m by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need m*m+2*m, prefer m*m+m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m*m+m+n, prefer m*m+m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,work(iu + ldwrku), &
                                    ldwrku)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,work(iu),ldwrku,s,rwork(ie),work( &
                                    itauq),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_wlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+(m-1)*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (cworkspace: need m*m+3*m, prefer m*m+2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (cworkspace: need m*m)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,m,m,0,s,rwork(ie),work(iu),ldwrku, &
                                    u,ldu,cdum,1,rwork(irwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (cworkspace: need m*m)
                          ! (rworkspace: 0)
                          call la_wgemm('N','N',m,n,m,cone,work(iu),ldwrku,vt,ldvt, &
                                     czero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_wlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (cworkspace: need 2*m, prefer m+m*nb)
                          ! (rworkspace: 0)
                          call la_wgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (cworkspace: need m+n, prefer m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_wlacpy('L',m,m,a,lda,u,ldu)
                          call la_wlaset('U',m - 1,m - 1,czero,czero,u(1,2),ldu)
                          ie = 1
                          itauq = itau
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (cworkspace: need 3*m, prefer 2*m+2*m*nb)
                          ! (rworkspace: need m)
                          call la_wgebrd(m,m,u,ldu,s,rwork(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (cworkspace: need 2*m+n, prefer 2*m+n*nb)
                          ! (rworkspace: 0)
                          call la_wunmbr('P','L','C',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                          ! (rworkspace: 0)
                          call la_wungbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          irwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (cworkspace: 0)
                          ! (rworkspace: need bdspac)
                          call la_wbdsqr('U',m,n,m,0,s,rwork(ie),vt,ldvt,u,ldu, &
                                    cdum,1,rwork(irwork),info)
                       end if
                    end if
                 end if
              else
                 ! n < mnthr
                 ! path 10t(n greater than m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = 1
                 itaup = itauq + m
                 iwork = itaup + m
                 ! bidiagonalize a
                 ! (cworkspace: need 2*m+n, prefer 2*m+(m+n)*nb)
                 ! (rworkspace: m)
                 call la_wgebrd(m,n,a,lda,s,rwork(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (cworkspace: need 3*m-1, prefer 2*m+(m-1)*nb)
                    ! (rworkspace: 0)
                    call la_wlacpy('L',m,m,a,lda,u,ldu)
                    call la_wungbr('Q',m,m,n,u,ldu,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (cworkspace: need 2*m+nrvt, prefer 2*m+nrvt*nb)
                    ! (rworkspace: 0)
                    call la_wlacpy('U',m,n,a,lda,vt,ldvt)
                    if (wntva) nrvt = n
                    if (wntvs) nrvt = m
                    call la_wungbr('P',nrvt,n,m,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*m-1, prefer 2*m+(m-1)*nb)
                    ! (rworkspace: 0)
                    call la_wungbr('Q',m,m,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (cworkspace: need 3*m, prefer 2*m+m*nb)
                    ! (rworkspace: 0)
                    call la_wungbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 irwork = ie + m
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_wbdsqr('L',m,ncvt,nru,0,s,rwork(ie),vt,ldvt,u,ldu, &
                              cdum,1,rwork(irwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_wbdsqr('L',m,ncvt,nru,0,s,rwork(ie),a,lda,u,ldu,cdum, &
                               1,rwork(irwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (cworkspace: 0)
                    ! (rworkspace: need bdspac)
                    call la_wbdsqr('L',m,ncvt,nru,0,s,rwork(ie),vt,ldvt,a,lda, &
                              cdum,1,rwork(irwork),info)
                 end if
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn - 1, &
                         1,rwork(ie),minmn,ierr)
              if (anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn - 1, &
                         1,rwork(ie),minmn,ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = maxwrk
           return
     end subroutine la_wgesvd
#endif

     !> CGESVDQ: computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N unitary matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_cgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,cwork,lcwork,rwork,lrwork,info)
        use la_constants_sp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lcwork
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: u(ldu,*),v(ldv,*),cwork(*)
           real(sp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_cgelqf,lwrk_cgesvd,lwrk_cgesvd2,lwrk_cgeqp3, &
           lwrk_cgeqrf,lwrk_cunmlq,lwrk_cunmqr,lwrk_cunmqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lwunq,lwunq2,lwunlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(sp) :: big,epsln,rtmp,sconda,sfmin
           complex(sp) :: ctmp
           ! Local Arrays
           complex(sp) :: cdummy(1)
           real(sp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,conjg,max,min,real,sqrt
           ! Executable Statements
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              iminwrk = max(1,n + m - 1)
              rminwrk = max(2,m,5*n)
           else
              iminwrk = max(1,n)
              rminwrk = max(2,5*n)
           end if
           lquery = (liwork == -1 .or. lcwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
           ! compute workspace
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lcwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_cgeqp3 Of An M X N Matrix
              lwqp3 = n + 1
              ! Minimal Workspace Length For la_cunmqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lwunq = max(n,1)
              else if (wntua) then
                  lwunq = max(m,1)
              end if
              ! Minimal Workspace Length For la_cpocon Of An N X N Matrix
              lwcon = 2*n
              ! la_cgesvd Of An N X N Matrix
              lwsvd = max(3*n,1)
              if (lquery) then
                  call la_cgeqp3(m,n,a,lda,iwork,cdummy,cdummy,-1,rdummy,ierr)

                  lwrk_cgeqp3 = int(cdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_cunmqr('L','N',m,n,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_cunmqr = int(cdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_cunmqr('L','N',m,m,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_cunmqr = int(cdummy(1),KIND=ilp)
                  else
                      lwrk_cunmqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_cgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                rdummy,ierr)
                      lwrk_cgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_cgeqp3,n + lwcon,lwrk_cgesvd)
                      else
                         optwrk = max(n + lwrk_cgeqp3,lwrk_cgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lwunq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lwunq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_cgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     else
                        call la_cgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     end if
                     lwrk_cgesvd = int(cdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_cgeqp3,lwcon,lwrk_cgesvd,lwrk_cunmqr)
                     else
                         optwrk = n + max(lwrk_cgeqp3,lwrk_cgesvd,lwrk_cunmqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_cgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      else
                          call la_cgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      end if
                      lwrk_cgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_cgeqp3,lwcon,lwrk_cgesvd)
                      else
                          optwrk = n + max(lwrk_cgeqp3,lwrk_cgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_cgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_cgesvd
                         lwsvd2 = max(3*(n/2),1)
                         lwunq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lwunq2,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_cgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(3*(n/2),1)
                         lwunlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lwunlq,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_cgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_cgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_cgeqp3,lwrk_cgesvd,lwrk_cunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_cgeqrf(n,n/2,u,ldu,cdummy,cdummy,-1,ierr)
                            lwrk_cgeqrf = int(cdummy(1),KIND=ilp)
                            call la_cgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                       -1,rdummy,ierr)
                            lwrk_cgesvd2 = int(cdummy(1),KIND=ilp)
                            call la_cunmqr('R','C',n,n,n/2,u,ldu,cdummy,v,ldv, &
                                      cdummy,-1,ierr)
                            lwrk_cunmqr2 = int(cdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_cgeqp3,n/2 + lwrk_cgeqrf,n/2 + lwrk_cgesvd2,n/2 + &
                                      lwrk_cunmqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_cgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_cgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_cgeqp3,lwrk_cgesvd,lwrk_cunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_cgelqf(n/2,n,u,ldu,cdummy,cdummy,-1,ierr)
                           lwrk_cgelqf = int(cdummy(1),KIND=ilp)
                           call la_cgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                      -1,rdummy,ierr)
                           lwrk_cgesvd2 = int(cdummy(1),KIND=ilp)
                           call la_cunmlq('R','N',n,n,n/2,u,ldu,cdummy,v,ldv,cdummy, &
                                     -1,ierr)
                           lwrk_cunmlq = int(cdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_cgeqp3,n/2 + lwrk_cgelqf,n/2 + lwrk_cgesvd2,n/2 + &
                                     lwrk_cunmlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lcwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('CGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               cwork(1) = optwrk
               cwork(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_slamch('O')
           ascaled = .false.
           if (rowprm) then
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_icamax(n,a(p,1),lda)) )
                     ! [[la_clange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_clange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('CGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_isamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_slaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_claset('G',m,n,czero,cone,u,ldu)
                    if (wntua) call la_claset('G',m,m,czero,cone,u,ldu)
                    if (wntva) call la_claset('G',n,n,czero,cone,v,ldv)
                    if (wntuf) then
                        call la_claset('G',n,1,czero,czero,cwork,n)
                        call la_claset('G',m,n,czero,cone,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=sp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_clascl('G',0,0,sqrt(real(m,KIND=sp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_claswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_clange('M',m,n,a,lda,rwork)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('CGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=sp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_clascl('G',0,0,sqrt(real(m,KIND=sp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_cgeqp3(m,n,a,lda,iwork,cwork,cwork(n + 1),lcwork - n,rwork,ierr)

          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_slamch('E')
           sfmin = la_slamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=sp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_slamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_clacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_scnrm2(p,v(1,p),1)
                       call la_csscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_cpocon('U',nr,v,ldv,one,rtmp,cwork,rwork,ierr)

                    else
                        call la_cpocon('U',nr,v,ldv,one,rtmp,cwork(n + 1),rwork,ierr)

                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**h = [a](1:nr,1:n)**h
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**h and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    a(p,p) = conjg(a(p,p))
                    do q = p + 1,n
                       a(q,p) = conjg(a(p,q))
                       if (q <= nr) a(p,q) = czero
                    end do
                 end do
                 call la_cgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,a(2,1),lda)

                 call la_cgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_cgesvd to r**h
                  ! .. copy r**h into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,u(1,2),ldu)

                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as conjugate transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_cgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                    end do
              else
                  ! Apply la_cgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_clacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_cgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_claset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_claset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                     call la_claset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_cunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_claswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_cgesvd to r**h
                  ! .. copy r**h into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_cgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_clapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_claset('G',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                     call la_cgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     do p = 1,n
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,n
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                     end do
                     call la_clapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_cgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_clacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_cgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_clapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_claset('G',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                      call la_cgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                lcwork - n,rwork,info)
                      call la_clapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the adjoint of the matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_cgesvd to r**h [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite [v], the nr right
                 ! singular vectors of r**h stored in [u](1:nr,1:nr) as conjugate
                 ! transposed
                    call la_cgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    ! Assemble V
                    do p = 1,nr
                       v(p,p) = conjg(v(p,p))
                       do q = p + 1,nr
                          ctmp = conjg(v(q,p))
                          v(q,p) = conjg(v(p,q))
                          v(p,q) = ctmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_clapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_claset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_claset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_claset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'cgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                        call la_claset('A',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                        call la_cgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                                  lcwork - n,rwork,info)
                        do p = 1,n
                           v(p,p) = conjg(v(p,p))
                           do q = p + 1,n
                              ctmp = conjg(v(q,p))
                              v(q,p) = conjg(v(p,q))
                              v(p,q) = ctmp
                           end do
                        end do
                        call la_clapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           u(p,p) = conjg(u(p,p))
                           do q = p + 1,n
                              ctmp = conjg(u(q,p))
                              u(q,p) = conjg(u(p,q))
                              u(p,q) = ctmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_claset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_claset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_claset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**h into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,u(1,nr + 2),ldu)

                        call la_cgeqrf(n,nr,u(1,nr + 1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                  lcwork - n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = conjg(u(p,nr + q))
                            end do
                        end do
                       call la_claset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)
                       call la_cgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_claset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_claset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_claset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_cunmqr('R','C',n,n,nr,u(1,nr + 1),ldu,cwork(n + 1),v,ldv, &
                                 cwork(n + nr + 1),lcwork - n - nr,ierr)
                       call la_clapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_claset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_claset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_claset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_cgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_clacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_cgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_clapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_claset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_claset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_claset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'cgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_clacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_claset('A',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                       call la_cgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                 lcwork - n,rwork,info)
                       call la_clapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the adjoint of the matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_claset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_claset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_claset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_clacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_claset('L',nr - 1,nr - 1,czero,czero,u(nr + 2,1),ldu)

                       call la_cgelqf(nr,n,u(nr + 1,1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                 lcwork - n - nr,ierr)
                       call la_clacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_claset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                       call la_cgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_claset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_claset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_claset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_cunmlq('R','N',n,n,nr,u(nr + 1,1),ldu,cwork(n + 1),v,ldv,cwork(n + &
                                 nr + 1),lcwork - n - nr,ierr)
                       call la_clapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_claset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_claset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_claset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**h or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_cunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_claswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_slaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_slascl('G',0,0,one,sqrt(real(m,KIND=sp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_cgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_cgesvdq
     !> ZCGESVDQ computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N unitary matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_zgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,cwork,lcwork,rwork,lrwork,info)
        use la_constants_dp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lcwork
           ! Array Arguments
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: u(ldu,*),v(ldv,*),cwork(*)
           real(dp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_zgelqf,lwrk_zgesvd,lwrk_zgesvd2,lwrk_zgeqp3, &
           lwrk_zgeqrf,lwrk_zunmlq,lwrk_zunmqr,lwrk_zunmqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lwunq,lwunq2,lwunlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(dp) :: big,epsln,rtmp,sconda,sfmin
           complex(dp) :: ctmp
           ! Local Arrays
           complex(dp) :: cdummy(1)
           real(dp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,conjg,max,min,real,sqrt
           ! Executable Statements
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              iminwrk = max(1,n + m - 1)
              rminwrk = max(2,m,5*n)
           else
              iminwrk = max(1,n)
              rminwrk = max(2,5*n)
           end if
           lquery = (liwork == -1 .or. lcwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lcwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_zgeqp3 Of An M X N Matrix
              lwqp3 = n + 1
              ! Minimal Workspace Length For la_zunmqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lwunq = max(n,1)
              else if (wntua) then
                  lwunq = max(m,1)
              end if
              ! Minimal Workspace Length For la_zpocon Of An N X N Matrix
              lwcon = 2*n
              ! la_zgesvd Of An N X N Matrix
              lwsvd = max(3*n,1)
              if (lquery) then
                  call la_zgeqp3(m,n,a,lda,iwork,cdummy,cdummy,-1,rdummy,ierr)

                  lwrk_zgeqp3 = int(cdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_zunmqr('L','N',m,n,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_zunmqr = int(cdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_zunmqr('L','N',m,m,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_zunmqr = int(cdummy(1),KIND=ilp)
                  else
                      lwrk_zunmqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_zgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                rdummy,ierr)
                      lwrk_zgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_zgeqp3,n + lwcon,lwrk_zgesvd)
                      else
                         optwrk = max(n + lwrk_zgeqp3,lwrk_zgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lwunq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lwunq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_zgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     else
                        call la_zgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     end if
                     lwrk_zgesvd = int(cdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_zgeqp3,lwcon,lwrk_zgesvd,lwrk_zunmqr)
                     else
                         optwrk = n + max(lwrk_zgeqp3,lwrk_zgesvd,lwrk_zunmqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_zgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      else
                          call la_zgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      end if
                      lwrk_zgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_zgeqp3,lwcon,lwrk_zgesvd)
                      else
                          optwrk = n + max(lwrk_zgeqp3,lwrk_zgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_zgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_zgesvd
                         lwsvd2 = max(3*(n/2),1)
                         lwunq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lwunq2,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_zgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(3*(n/2),1)
                         lwunlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lwunlq,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_zgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_zgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_zgeqp3,lwrk_zgesvd,lwrk_zunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_zgeqrf(n,n/2,u,ldu,cdummy,cdummy,-1,ierr)
                            lwrk_zgeqrf = int(cdummy(1),KIND=ilp)
                            call la_zgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                       -1,rdummy,ierr)
                            lwrk_zgesvd2 = int(cdummy(1),KIND=ilp)
                            call la_zunmqr('R','C',n,n,n/2,u,ldu,cdummy,v,ldv, &
                                      cdummy,-1,ierr)
                            lwrk_zunmqr2 = int(cdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_zgeqp3,n/2 + lwrk_zgeqrf,n/2 + lwrk_zgesvd2,n/2 + &
                                      lwrk_zunmqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_zgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_zgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_zgeqp3,lwrk_zgesvd,lwrk_zunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_zgelqf(n/2,n,u,ldu,cdummy,cdummy,-1,ierr)
                           lwrk_zgelqf = int(cdummy(1),KIND=ilp)
                           call la_zgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                      -1,rdummy,ierr)
                           lwrk_zgesvd2 = int(cdummy(1),KIND=ilp)
                           call la_zunmlq('R','N',n,n,n/2,u,ldu,cdummy,v,ldv,cdummy, &
                                     -1,ierr)
                           lwrk_zunmlq = int(cdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_zgeqp3,n/2 + lwrk_zgelqf,n/2 + lwrk_zgesvd2,n/2 + &
                                     lwrk_zunmlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lcwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('ZGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               cwork(1) = optwrk
               cwork(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_dlamch('O')
           ascaled = .false.
           if (rowprm) then
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_izamax(n,a(p,1),lda)) )
                     ! [[la_zlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_zlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('ZGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_idamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_dlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_zlaset('G',m,n,czero,cone,u,ldu)
                    if (wntua) call la_zlaset('G',m,m,czero,cone,u,ldu)
                    if (wntva) call la_zlaset('G',n,n,czero,cone,v,ldv)
                    if (wntuf) then
                        call la_zlaset('G',n,1,czero,czero,cwork,n)
                        call la_zlaset('G',m,n,czero,cone,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=dp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_zlascl('G',0,0,sqrt(real(m,KIND=dp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_zlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_zlange('M',m,n,a,lda,rwork)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('ZGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=dp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_zlascl('G',0,0,sqrt(real(m,KIND=dp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_zgeqp3(m,n,a,lda,iwork,cwork,cwork(n + 1),lcwork - n,rwork,ierr)

          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_dlamch('E')
           sfmin = la_dlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=dp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_dlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_zlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_dznrm2(p,v(1,p),1)
                       call la_zdscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_zpocon('U',nr,v,ldv,one,rtmp,cwork,rwork,ierr)

                    else
                        call la_zpocon('U',nr,v,ldv,one,rtmp,cwork(n + 1),rwork,ierr)

                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**h = [a](1:nr,1:n)**h
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**h and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    a(p,p) = conjg(a(p,p))
                    do q = p + 1,n
                       a(q,p) = conjg(a(p,q))
                       if (q <= nr) a(p,q) = czero
                    end do
                 end do
                 call la_zgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,a(2,1),lda)

                 call la_zgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_zgesvd to r**h
                  ! .. copy r**h into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,u(1,2),ldu)

                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as conjugate transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_zgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                    end do
              else
                  ! Apply la_zgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_zlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_zgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_zlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_zlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                     call la_zlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_zunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_zlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_zgesvd to r**h
                  ! .. copy r**h into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_zgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_zlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_zlaset('G',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                     call la_zgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     do p = 1,n
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,n
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                     end do
                     call la_zlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_zgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_zlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_zgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_zlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_zlaset('G',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                      call la_zgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                lcwork - n,rwork,info)
                      call la_zlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the adjoint of the matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_zgesvd to r**h [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite [v], the nr right
                 ! singular vectors of r**h stored in [u](1:nr,1:nr) as conjugate
                 ! transposed
                    call la_zgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    ! Assemble V
                    do p = 1,nr
                       v(p,p) = conjg(v(p,p))
                       do q = p + 1,nr
                          ctmp = conjg(v(q,p))
                          v(q,p) = conjg(v(p,q))
                          v(p,q) = ctmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_zlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_zlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_zlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_zlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'zgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                        call la_zlaset('A',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                        call la_zgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                                  lcwork - n,rwork,info)
                        do p = 1,n
                           v(p,p) = conjg(v(p,p))
                           do q = p + 1,n
                              ctmp = conjg(v(q,p))
                              v(q,p) = conjg(v(p,q))
                              v(p,q) = ctmp
                           end do
                        end do
                        call la_zlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           u(p,p) = conjg(u(p,p))
                           do q = p + 1,n
                              ctmp = conjg(u(q,p))
                              u(q,p) = conjg(u(p,q))
                              u(p,q) = ctmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_zlaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_zlaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_zlaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**h into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,u(1,nr + 2),ldu)

                        call la_zgeqrf(n,nr,u(1,nr + 1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                  lcwork - n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = conjg(u(p,nr + q))
                            end do
                        end do
                       call la_zlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)
                       call la_zgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_zlaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_zlaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_zlaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_zunmqr('R','C',n,n,nr,u(1,nr + 1),ldu,cwork(n + 1),v,ldv, &
                                 cwork(n + nr + 1),lcwork - n - nr,ierr)
                       call la_zlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_zlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_zlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_zlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_zgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_zlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_zgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_zlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_zlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_zlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_zlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'zgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_zlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_zlaset('A',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                       call la_zgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                 lcwork - n,rwork,info)
                       call la_zlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the adjoint of the matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_zlaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_zlaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_zlaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_zlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_zlaset('L',nr - 1,nr - 1,czero,czero,u(nr + 2,1),ldu)

                       call la_zgelqf(nr,n,u(nr + 1,1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                 lcwork - n - nr,ierr)
                       call la_zlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_zlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                       call la_zgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_zlaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_zlaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_zlaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_zunmlq('R','N',n,n,nr,u(nr + 1,1),ldu,cwork(n + 1),v,ldv,cwork(n + &
                                 nr + 1),lcwork - n - nr,ierr)
                       call la_zlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_zlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_zlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_zlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**h or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_zunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_zlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_dlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_dlascl('G',0,0,one,sqrt(real(m,KIND=dp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_zgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_zgesvdq
#ifdef LA_WITH_XDP
     !> ZCGESVDQ computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N unitary matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_ygesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,cwork,lcwork,rwork,lrwork,info)
        use la_constants_xdp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lcwork
           ! Array Arguments
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: u(ldu,*),v(ldv,*),cwork(*)
           real(xdp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_ygelqf,lwrk_ygesvd,lwrk_ygesvd2,lwrk_ygeqp3, &
           lwrk_ygeqrf,lwrk_yunmlq,lwrk_yunmqr,lwrk_yunmqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lwunq,lwunq2,lwunlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(xdp) :: big,epsln,rtmp,sconda,sfmin
           complex(xdp) :: ctmp
           ! Local Arrays
           complex(xdp) :: cdummy(1)
           real(xdp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,conjg,max,min,real,sqrt
           ! Executable Statements
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              iminwrk = max(1,n + m - 1)
              rminwrk = max(2,m,5*n)
           else
              iminwrk = max(1,n)
              rminwrk = max(2,5*n)
           end if
           lquery = (liwork == -1 .or. lcwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lcwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_ygeqp3 Of An M X N Matrix
              lwqp3 = n + 1
              ! Minimal Workspace Length For la_yunmqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lwunq = max(n,1)
              else if (wntua) then
                  lwunq = max(m,1)
              end if
              ! Minimal Workspace Length For la_ypocon Of An N X N Matrix
              lwcon = 2*n
              ! la_ygesvd Of An N X N Matrix
              lwsvd = max(3*n,1)
              if (lquery) then
                  call la_ygeqp3(m,n,a,lda,iwork,cdummy,cdummy,-1,rdummy,ierr)

                  lwrk_ygeqp3 = int(cdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_yunmqr('L','N',m,n,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_yunmqr = int(cdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_yunmqr('L','N',m,m,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_yunmqr = int(cdummy(1),KIND=ilp)
                  else
                      lwrk_yunmqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_ygesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                rdummy,ierr)
                      lwrk_ygesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_ygeqp3,n + lwcon,lwrk_ygesvd)
                      else
                         optwrk = max(n + lwrk_ygeqp3,lwrk_ygesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lwunq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lwunq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_ygesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     else
                        call la_ygesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     end if
                     lwrk_ygesvd = int(cdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_ygeqp3,lwcon,lwrk_ygesvd,lwrk_yunmqr)
                     else
                         optwrk = n + max(lwrk_ygeqp3,lwrk_ygesvd,lwrk_yunmqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_ygesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      else
                          call la_ygesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      end if
                      lwrk_ygesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_ygeqp3,lwcon,lwrk_ygesvd)
                      else
                          optwrk = n + max(lwrk_ygeqp3,lwrk_ygesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_ygeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_ygesvd
                         lwsvd2 = max(3*(n/2),1)
                         lwunq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lwunq2,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_ygelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(3*(n/2),1)
                         lwunlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lwunlq,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_ygesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_ygesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_ygeqp3,lwrk_ygesvd,lwrk_yunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_ygeqrf(n,n/2,u,ldu,cdummy,cdummy,-1,ierr)
                            lwrk_ygeqrf = int(cdummy(1),KIND=ilp)
                            call la_ygesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                       -1,rdummy,ierr)
                            lwrk_ygesvd2 = int(cdummy(1),KIND=ilp)
                            call la_yunmqr('R','C',n,n,n/2,u,ldu,cdummy,v,ldv, &
                                      cdummy,-1,ierr)
                            lwrk_yunmqr2 = int(cdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_ygeqp3,n/2 + lwrk_ygeqrf,n/2 + lwrk_ygesvd2,n/2 + &
                                      lwrk_yunmqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_ygesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_ygesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_ygeqp3,lwrk_ygesvd,lwrk_yunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_ygelqf(n/2,n,u,ldu,cdummy,cdummy,-1,ierr)
                           lwrk_ygelqf = int(cdummy(1),KIND=ilp)
                           call la_ygesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                      -1,rdummy,ierr)
                           lwrk_ygesvd2 = int(cdummy(1),KIND=ilp)
                           call la_yunmlq('R','N',n,n,n/2,u,ldu,cdummy,v,ldv,cdummy, &
                                     -1,ierr)
                           lwrk_yunmlq = int(cdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_ygeqp3,n/2 + lwrk_ygelqf,n/2 + lwrk_ygesvd2,n/2 + &
                                     lwrk_yunmlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lcwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('YGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               cwork(1) = optwrk
               cwork(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_xlamch('O')
           ascaled = .false.
           if (rowprm) then
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_iyamax(n,a(p,1),lda)) )
                     ! [[la_ylange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_ylange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('YGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_ixamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_xlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_ylaset('G',m,n,czero,cone,u,ldu)
                    if (wntua) call la_ylaset('G',m,m,czero,cone,u,ldu)
                    if (wntva) call la_ylaset('G',n,n,czero,cone,v,ldv)
                    if (wntuf) then
                        call la_ylaset('G',n,1,czero,czero,cwork,n)
                        call la_ylaset('G',m,n,czero,cone,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=xdp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_ylascl('G',0,0,sqrt(real(m,KIND=xdp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_ylaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_ylange('M',m,n,a,lda,rwork)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('YGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=xdp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_ylascl('G',0,0,sqrt(real(m,KIND=xdp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_ygeqp3(m,n,a,lda,iwork,cwork,cwork(n + 1),lcwork - n,rwork,ierr)

          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_xlamch('E')
           sfmin = la_xlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=xdp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_xlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_ylacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_xynrm2(p,v(1,p),1)
                       call la_yxscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_ypocon('U',nr,v,ldv,one,rtmp,cwork,rwork,ierr)

                    else
                        call la_ypocon('U',nr,v,ldv,one,rtmp,cwork(n + 1),rwork,ierr)

                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**h = [a](1:nr,1:n)**h
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**h and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    a(p,p) = conjg(a(p,p))
                    do q = p + 1,n
                       a(q,p) = conjg(a(p,q))
                       if (q <= nr) a(p,q) = czero
                    end do
                 end do
                 call la_ygesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,a(2,1),lda)

                 call la_ygesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_ygesvd to r**h
                  ! .. copy r**h into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,u(1,2),ldu)

                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as conjugate transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_ygesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                    end do
              else
                  ! Apply la_ygesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_ylacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_ygesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_ylaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_ylaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                     call la_ylaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_yunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_ylaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_ygesvd to r**h
                  ! .. copy r**h into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_ygesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_ylapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_ylaset('G',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                     call la_ygesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     do p = 1,n
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,n
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                     end do
                     call la_ylapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_ygesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_ylacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_ygesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_ylapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_ylaset('G',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                      call la_ygesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                lcwork - n,rwork,info)
                      call la_ylapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the adjoint of the matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_ygesvd to r**h [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite [v], the nr right
                 ! singular vectors of r**h stored in [u](1:nr,1:nr) as conjugate
                 ! transposed
                    call la_ygesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    ! Assemble V
                    do p = 1,nr
                       v(p,p) = conjg(v(p,p))
                       do q = p + 1,nr
                          ctmp = conjg(v(q,p))
                          v(q,p) = conjg(v(p,q))
                          v(p,q) = ctmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_ylapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_ylaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_ylaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_ylaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'ygesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                        call la_ylaset('A',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                        call la_ygesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                                  lcwork - n,rwork,info)
                        do p = 1,n
                           v(p,p) = conjg(v(p,p))
                           do q = p + 1,n
                              ctmp = conjg(v(q,p))
                              v(q,p) = conjg(v(p,q))
                              v(p,q) = ctmp
                           end do
                        end do
                        call la_ylapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           u(p,p) = conjg(u(p,p))
                           do q = p + 1,n
                              ctmp = conjg(u(q,p))
                              u(q,p) = conjg(u(p,q))
                              u(p,q) = ctmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_ylaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_ylaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_ylaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**h into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,u(1,nr + 2),ldu)

                        call la_ygeqrf(n,nr,u(1,nr + 1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                  lcwork - n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = conjg(u(p,nr + q))
                            end do
                        end do
                       call la_ylaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)
                       call la_ygesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_ylaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_ylaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_ylaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_yunmqr('R','C',n,n,nr,u(1,nr + 1),ldu,cwork(n + 1),v,ldv, &
                                 cwork(n + nr + 1),lcwork - n - nr,ierr)
                       call la_ylapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_ylaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_ylaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_ylaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_ygesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_ylacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_ygesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_ylapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_ylaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_ylaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_ylaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'ygesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_ylacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_ylaset('A',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                       call la_ygesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                 lcwork - n,rwork,info)
                       call la_ylapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the adjoint of the matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_ylaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_ylaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_ylaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_ylacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_ylaset('L',nr - 1,nr - 1,czero,czero,u(nr + 2,1),ldu)

                       call la_ygelqf(nr,n,u(nr + 1,1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                 lcwork - n - nr,ierr)
                       call la_ylacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_ylaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                       call la_ygesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_ylaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_ylaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_ylaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_yunmlq('R','N',n,n,nr,u(nr + 1,1),ldu,cwork(n + 1),v,ldv,cwork(n + &
                                 nr + 1),lcwork - n - nr,ierr)
                       call la_ylapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_ylaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_ylaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_ylaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**h or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_yunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_ylaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_xlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_xlascl('G',0,0,one,sqrt(real(m,KIND=xdp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_ygesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_ygesvdq
#endif
#ifdef LA_WITH_QP
     !> ZCGESVDQ computes the singular value decomposition (SVD) of a complex
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N unitary matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_wgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,cwork,lcwork,rwork,lrwork,info)
        use la_constants_qp
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lcwork
           ! Array Arguments
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: u(ldu,*),v(ldv,*),cwork(*)
           real(qp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_wgelqf,lwrk_wgesvd,lwrk_wgesvd2,lwrk_wgeqp3, &
           lwrk_wgeqrf,lwrk_wunmlq,lwrk_wunmqr,lwrk_wunmqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lwunq,lwunq2,lwunlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(qp) :: big,epsln,rtmp,sconda,sfmin
           complex(qp) :: ctmp
           ! Local Arrays
           complex(qp) :: cdummy(1)
           real(qp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,conjg,max,min,real,sqrt
           ! Executable Statements
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              iminwrk = max(1,n + m - 1)
              rminwrk = max(2,m,5*n)
           else
              iminwrk = max(1,n)
              rminwrk = max(2,5*n)
           end if
           lquery = (liwork == -1 .or. lcwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lcwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_wgeqp3 Of An M X N Matrix
              lwqp3 = n + 1
              ! Minimal Workspace Length For la_wunmqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lwunq = max(n,1)
              else if (wntua) then
                  lwunq = max(m,1)
              end if
              ! Minimal Workspace Length For la_wpocon Of An N X N Matrix
              lwcon = 2*n
              ! la_wgesvd Of An N X N Matrix
              lwsvd = max(3*n,1)
              if (lquery) then
                  call la_wgeqp3(m,n,a,lda,iwork,cdummy,cdummy,-1,rdummy,ierr)

                  lwrk_wgeqp3 = int(cdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_wunmqr('L','N',m,n,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_wunmqr = int(cdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_wunmqr('L','N',m,m,n,a,lda,cdummy,u,ldu,cdummy,-1, &
                                ierr)
                      lwrk_wunmqr = int(cdummy(1),KIND=ilp)
                  else
                      lwrk_wunmqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_wgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                rdummy,ierr)
                      lwrk_wgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_wgeqp3,n + lwcon,lwrk_wgesvd)
                      else
                         optwrk = max(n + lwrk_wgeqp3,lwrk_wgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lwunq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lwunq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_wgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     else
                        call la_wgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                     end if
                     lwrk_wgesvd = int(cdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_wgeqp3,lwcon,lwrk_wgesvd,lwrk_wunmqr)
                     else
                         optwrk = n + max(lwrk_wgeqp3,lwrk_wgesvd,lwrk_wunmqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_wgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      else
                          call la_wgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,- &
                                    1,rdummy,ierr)
                      end if
                      lwrk_wgesvd = int(cdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_wgeqp3,lwcon,lwrk_wgesvd)
                      else
                          optwrk = n + max(lwrk_wgeqp3,lwrk_wgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Complex Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_wgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_wgesvd
                         lwsvd2 = max(3*(n/2),1)
                         lwunq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lwunq2,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lwunq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_wgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(3*(n/2),1)
                         lwunlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lwunlq,lwunq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_wgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_wgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_wgeqp3,lwrk_wgesvd,lwrk_wunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_wgeqrf(n,n/2,u,ldu,cdummy,cdummy,-1,ierr)
                            lwrk_wgeqrf = int(cdummy(1),KIND=ilp)
                            call la_wgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                       -1,rdummy,ierr)
                            lwrk_wgesvd2 = int(cdummy(1),KIND=ilp)
                            call la_wunmqr('R','C',n,n,n/2,u,ldu,cdummy,v,ldv, &
                                      cdummy,-1,ierr)
                            lwrk_wunmqr2 = int(cdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_wgeqp3,n/2 + lwrk_wgeqrf,n/2 + lwrk_wgesvd2,n/2 + &
                                      lwrk_wunmqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_wgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,cdummy,-1, &
                                  rdummy,ierr)
                        lwrk_wgesvd = int(cdummy(1),KIND=ilp)
                        optwrk = max(lwrk_wgeqp3,lwrk_wgesvd,lwrk_wunmqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_wgelqf(n/2,n,u,ldu,cdummy,cdummy,-1,ierr)
                           lwrk_wgelqf = int(cdummy(1),KIND=ilp)
                           call la_wgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,cdummy, &
                                      -1,rdummy,ierr)
                           lwrk_wgesvd2 = int(cdummy(1),KIND=ilp)
                           call la_wunmlq('R','N',n,n,n/2,u,ldu,cdummy,v,ldv,cdummy, &
                                     -1,ierr)
                           lwrk_wunmlq = int(cdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_wgeqp3,n/2 + lwrk_wgelqf,n/2 + lwrk_wgesvd2,n/2 + &
                                     lwrk_wunmlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lcwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('WGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               cwork(1) = optwrk
               cwork(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_qlamch('O')
           ascaled = .false.
           if (rowprm) then
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_iwamax(n,a(p,1),lda)) )
                     ! [[la_wlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_wlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('WGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_iqamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_qlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_wlaset('G',m,n,czero,cone,u,ldu)
                    if (wntua) call la_wlaset('G',m,m,czero,cone,u,ldu)
                    if (wntva) call la_wlaset('G',n,n,czero,cone,v,ldv)
                    if (wntuf) then
                        call la_wlaset('G',n,1,czero,czero,cwork,n)
                        call la_wlaset('G',m,n,czero,cone,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=qp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_wlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_wlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_wlange('M',m,n,a,lda,rwork)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('WGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=qp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_wlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_wgeqp3(m,n,a,lda,iwork,cwork,cwork(n + 1),lcwork - n,rwork,ierr)

          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_qlamch('E')
           sfmin = la_qlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=qp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_qlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_wlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_qwnrm2(p,v(1,p),1)
                       call la_wqscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_wpocon('U',nr,v,ldv,one,rtmp,cwork,rwork,ierr)

                    else
                        call la_wpocon('U',nr,v,ldv,one,rtmp,cwork(n + 1),rwork,ierr)

                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**h = [a](1:nr,1:n)**h
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**h and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    a(p,p) = conjg(a(p,p))
                    do q = p + 1,n
                       a(q,p) = conjg(a(p,q))
                       if (q <= nr) a(p,q) = czero
                    end do
                 end do
                 call la_wgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,a(2,1),lda)

                 call la_wgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,cwork,lcwork, &
                           rwork,info)
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_wgesvd to r**h
                  ! .. copy r**h into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,u(1,2),ldu)

                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as conjugate transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_wgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                    end do
              else
                  ! Apply la_wgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_wlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_wgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_wlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_wlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                     call la_wlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_wunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_wlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_wgesvd to r**h
                  ! .. copy r**h into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_wgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    do p = 1,nr
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_wlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_wlaset('G',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                     call la_wgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     do p = 1,n
                        v(p,p) = conjg(v(p,p))
                        do q = p + 1,n
                           ctmp = conjg(v(q,p))
                           v(q,p) = conjg(v(p,q))
                           v(p,q) = ctmp
                        end do
                     end do
                     call la_wlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_wgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_wlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_wgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_wlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_wlaset('G',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                      call la_wgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                lcwork - n,rwork,info)
                      call la_wlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the adjoint of the matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_wgesvd to r**h [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = conjg(a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                 ! .. the left singular vectors of r**h overwrite [v], the nr right
                 ! singular vectors of r**h stored in [u](1:nr,1:nr) as conjugate
                 ! transposed
                    call la_wgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                              lcwork - n,rwork,info)
                    ! Assemble V
                    do p = 1,nr
                       v(p,p) = conjg(v(p,p))
                       do q = p + 1,nr
                          ctmp = conjg(v(q,p))
                          v(q,p) = conjg(v(p,q))
                          v(p,q) = ctmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = conjg(v(q,p))
                           end do
                        end do
                    end if
                    call la_wlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        u(p,p) = conjg(u(p,p))
                        do q = p + 1,nr
                           ctmp = conjg(u(q,p))
                           u(q,p) = conjg(u(p,q))
                           u(p,q) = ctmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_wlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_wlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_wlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**h into [v] and overwrite [v] with the left singular
                  ! vectors of r**h
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'wgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                        call la_wlaset('A',n,n - nr,czero,czero,v(1,nr + 1),ldv)
                        call la_wgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,cwork(n + 1), &
                                  lcwork - n,rwork,info)
                        do p = 1,n
                           v(p,p) = conjg(v(p,p))
                           do q = p + 1,n
                              ctmp = conjg(v(q,p))
                              v(q,p) = conjg(v(p,q))
                              v(p,q) = ctmp
                           end do
                        end do
                        call la_wlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           u(p,p) = conjg(u(p,p))
                           do q = p + 1,n
                              ctmp = conjg(u(q,p))
                              u(q,p) = conjg(u(p,q))
                              u(p,q) = ctmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_wlaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_wlaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_wlaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**h into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = conjg(a(p,q))
                           end do
                        end do
                        if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,u(1,nr + 2),ldu)

                        call la_wgeqrf(n,nr,u(1,nr + 1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                  lcwork - n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = conjg(u(p,nr + q))
                            end do
                        end do
                       call la_wlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)
                       call la_wgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_wlaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_wlaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_wlaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_wunmqr('R','C',n,n,nr,u(1,nr + 1),ldu,cwork(n + 1),v,ldv, &
                                 cwork(n + nr + 1),lcwork - n - nr,ierr)
                       call la_wlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_wlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_wlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_wlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_wgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_wlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_wgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                               lcwork - n,rwork,info)
                     call la_wlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**h
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_wlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_wlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_wlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'wgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_wlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_wlaset('A',n - nr,n,czero,czero,v(nr + 1,1),ldv)
                       call la_wgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,cwork(n + 1), &
                                 lcwork - n,rwork,info)
                       call la_wlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the adjoint of the matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_wlaset('A',m - n,n,czero,czero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_wlaset('A',n,n1 - n,czero,czero,u(1,n + 1),ldu)
                             call la_wlaset('A',m - n,n1 - n,czero,cone,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_wlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_wlaset('L',nr - 1,nr - 1,czero,czero,u(nr + 2,1),ldu)

                       call la_wgelqf(nr,n,u(nr + 1,1),ldu,cwork(n + 1),cwork(n + nr + 1), &
                                 lcwork - n - nr,ierr)
                       call la_wlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_wlaset('U',nr - 1,nr - 1,czero,czero,v(1,2),ldv)

                       call la_wgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,cwork(n + nr + &
                                 1),lcwork - n - nr,rwork,info)
                       call la_wlaset('A',n - nr,nr,czero,czero,v(nr + 1,1),ldv)
                       call la_wlaset('A',nr,n - nr,czero,czero,v(1,nr + 1),ldv)
                       call la_wlaset('A',n - nr,n - nr,czero,cone,v(nr + 1,nr + 1),ldv)
                       call la_wunmlq('R','N',n,n,nr,u(nr + 1,1),ldu,cwork(n + 1),v,ldv,cwork(n + &
                                 nr + 1),lcwork - n - nr,ierr)
                       call la_wlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_wlaset('A',m - nr,nr,czero,czero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_wlaset('A',nr,n1 - nr,czero,czero,u(1,nr + 1),ldu)
                          call la_wlaset('A',m - nr,n1 - nr,czero,cone,u(nr + 1,nr + 1),ldu)

                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**h or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_wunmqr('L','N',m,n1,n,a,lda,cwork,u,ldu, &
                        cwork(n + 1),lcwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_wlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_qlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_qlascl('G',0,0,one,sqrt(real(m,KIND=qp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_wgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_wgesvdq
#endif

end module la_lapack_eigv_svd_drivers
